            {session ? (
              <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="flex items-center gap-3 p-1 pr-3 bg-gray-50 rounded-full border border-gray-100 hover:border-orange-200 transition-all"
                >
