import { supabase } from '../lib/supabase';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

/**
 * Syncs mock data to Supabase. Call this once to seed your database.
 */
export const syncMockDataToSupabase = async () => {
  const { data: existing } = await supabase.from('schemes').select('id').limit(1);
  if (existing && existing.length > 0) return;

  const { error } = await supabase.from('schemes').insert(MOCK_SCHEMES);
  if (error) console.error('Error seeding database:', error);
  else console.log('Database seeded with mock schemes!');
};

export const fetchAllSchemes = async (): Promise<Scheme[]> => {
  const { data, error } = await supabase
    .from('schemes')
    .select('*')
    .order('updatedAt', { ascending: false });

  if (error) {
    console.error('Error fetching schemes:', error);
    return MOCK_SCHEMES; // Fallback to mock data if table doesn't exist or query fails
  }
  return data as Scheme[];
};

export const fetchSchemeById = async (id: string): Promise<Scheme | null> => {
  const { data, error } = await supabase
    .from('schemes')
    .select('*')
    .eq('id', id)
    .single();

  if (error) {
    console.error('Error fetching scheme:', error);
    return MOCK_SCHEMES.find(s => s.id === id) || null;
  }
  return data as Scheme;
};

import { supabase } from '../lib/supabase';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

/**
 * Syncs mock data to Supabase. 
 * This attempts to populate your 'schemes' table if it is currently empty.
 */
export const syncMockDataToSupabase = async () => {
  try {
    // 1. Check if the table exists and has data
    const { data: existing, error: checkError } = await supabase
      .from('schemes')
      .select('id')
      .limit(1);

    if (checkError) {
      if (checkError.code === '42P01') {
        console.error('Error: The "schemes" table does not exist in your Supabase database. Please create it using the SQL editor.');
      } else {
        console.error('Error checking for existing schemes:', checkError.message, checkError.details);
      }
      return;
    }

    // 2. If table is empty, insert mock data
    if (!existing || existing.length === 0) {
      console.log('Database table "schemes" is empty. Seeding with initial data...');
      const { error: insertError } = await supabase.from('schemes').insert(MOCK_SCHEMES);

      if (insertError) {
        console.error('Error seeding database:', insertError.message, insertError.details);
      } else {
        console.log('Successfully seeded database with', MOCK_SCHEMES.length, 'schemes!');
      }
    }
  } catch (err) {
    console.error('Unexpected error during Supabase sync:', err);
  }
};

/**
 * Fetches all schemes from the Supabase 'schemes' table.
 * Falls back to local MOCK_SCHEMES if the request fails.
 */
export const fetchAllSchemes = async (): Promise<Scheme[]> => {
  try {
    const { data, error } = await supabase
      .from('schemes')
      .select('*')
      .order('updatedAt', { ascending: false });

    if (error) {
      console.error('Supabase fetch error (falling back to mock data):', error.message);
      return MOCK_SCHEMES;
    }

    return (data as Scheme[]) || MOCK_SCHEMES;
  } catch (err) {
    console.error('Unexpected error fetching schemes:', err);
    return MOCK_SCHEMES;
  }
};

/**
 * Fetches a single scheme by ID from Supabase.
 * Falls back to local MOCK_SCHEMES if the request fails.
 */
export const fetchSchemeById = async (id: string): Promise<Scheme | null> => {
  try {
    const { data, error } = await supabase
      .from('schemes')
      .select('*')
      .eq('id', id)
      .single();

    if (error) {
      console.error(`Supabase fetch error for ID ${id}:`, error.message);
      return MOCK_SCHEMES.find(s => s.id === id) || null;
    }

    return (data as Scheme) || null;
  } catch (err) {
    console.error('Unexpected error fetching scheme by ID:', err);
    return MOCK_SCHEMES.find(s => s.id === id) || null;
  }
};

