import { supabase } from '../lib/supabase';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

/**
 * Syncs mock data to Supabase. 
 * This attempts to populate your 'schemes' table if it is currently empty.
 */
export const syncMockDataToSupabase = async () => {
  try {
    // 1. Check if the table exists and has data
    const { data: existing, error: checkError } = await supabase
      .from('schemes')
      .select('id')
      .limit(1);

    if (checkError) {
      if (checkError.code === '42P01') {
        console.warn('The "schemes" table does not exist. Please run the SQL setup script in your Supabase Editor.');
      } else {
        console.error('Database connection error:', checkError.message);
      }
      return;
    }

    // 2. If table is empty, insert mock data
    if (!existing || existing.length === 0) {
      console.log('Seeding initial data...');
      const { error: insertError } = await supabase.from('schemes').insert(MOCK_SCHEMES);

      if (insertError) {
        if (insertError.code === '42501') {
          console.error('RLS Violation: Please add the INSERT policy to your "schemes" table in Supabase.');
        } else {
          console.error('Seeding error:', insertError.message);
        }
      } else {
        console.log('Database successfully seeded!');
      }
    }
  } catch (err) {
    console.error('Unexpected sync error:', err);
  }
};

export const fetchAllSchemes = async (): Promise<Scheme[]> => {
  try {
    const { data, error } = await supabase
      .from('schemes')
      .select('*')
      .order('updatedAt', { ascending: false });

    if (error) return MOCK_SCHEMES;
    return (data as Scheme[]) || MOCK_SCHEMES;
  } catch (err) {
    return MOCK_SCHEMES;
  }
};

export const fetchSchemeById = async (id: string): Promise<Scheme | null> => {
  try {
    const { data, error } = await supabase
      .from('schemes')
      .select('*')
      .eq('id', id)
      .single();

    if (error) return MOCK_SCHEMES.find(s => s.id === id) || null;
    return (data as Scheme) || null;
  } catch (err) {
    return MOCK_SCHEMES.find(s => s.id === id) || null;
  }
};

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Search, Filter, ChevronLeft, ChevronRight, Check, Sparkles, ChevronDown, User as UserIcon } from 'lucide-react';
import { MOCK_SCHEMES, CATEGORIES, INDIAN_STATES_UTS } from '../constants';
import { searchSchemesAI, getAIRecommendations } from '../services/geminiService';
import { UserProfile, Scheme } from '../types';
import { supabase } from '../lib/supabase';

const FindSchemes: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'eligibility' | 'browse'>(searchParams.get('q') || searchParams.get('category') ? 'browse' : 'eligibility');

  // Browsing/Search state
  const [schemes, setSchemes] = useState<Scheme[]>(MOCK_SCHEMES);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState(searchParams.get('q') || '');
  const [selectedCategories, setSelectedCategories] = useState<string[]>(searchParams.get('category') ? [searchParams.get('category')!] : []);
  const [schemeLevel, setSchemeLevel] = useState<string>('All Levels');
  const [isAiFiltered, setIsAiFiltered] = useState(false);

  // Eligibility Wizard state
  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<UserProfile>({
      age: undefined,
      gender: 'Male',
      state: '',
      occupation: '',
      income: '',
      category: 'General' 
  });
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setIsAuthenticated(true);
        // Fetch real profile data from database to auto-fill
        const { data: profileData } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single();

        if (profileData) {
          setProfile({
            age: profileData.age,
            gender: profile.gender, // Gender isn't in current profile table, but we can assume or skip
            state: profileData.state || '',
            occupation: '', // Need to add to profile table if needed
            income: '',
            category: profileData.category || 'General'
          });
        }
      }
    };
    checkUser();
  }, []);

  const isStepValid = () => {
      switch(step) {
          case 1: return !!(profile.age && profile.gender);
          case 2: return !!profile.state;
          case 3: return !!(profile.occupation && profile.income);
          case 4: return true; 
          default: return false;
      }
  };

  useEffect(() => {
    if (activeTab === 'browse' && !isAiFiltered) {
        const performSearch = async () => {
            if (searchQuery) {
                setLoading(true);
                const results = await searchSchemesAI(searchQuery);
                setSchemes(results);
                setLoading(false);
            } else {
                let filtered = MOCK_SCHEMES;
                if (selectedCategories.length > 0) {
                    filtered = filtered.filter(s => selectedCategories.includes(s.category));
                }
                if (schemeLevel !== 'All Levels') {
                    filtered = filtered.filter(s => s.level === schemeLevel);
                }
                setSchemes(filtered);
            }
        };
        const debounce = setTimeout(performSearch, 300);
        return () => clearTimeout(debounce);
    }
  }, [searchQuery, selectedCategories, schemeLevel, activeTab, isAiFiltered]);

  const toggleCategory = (cat: string) => {
    setSelectedCategories(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  const handleFinalSubmit = async () => {
      setLoading(true);
      setActiveTab('browse');
      setIsAiFiltered(true);
      try {
          const recommendations = await getAIRecommendations(profile);
          setSchemes(recommendations);
      } catch (error) {
          console.error("Failed to get recommendations", error);
      } finally {
          setLoading(false);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const nextStep = () => {
    if (step === 4) {
        handleFinalSubmit();
    } else if (isStepValid()) {
        setStep(s => s + 1);
    }
  };

  const prevStep = () => setStep(s => Math.max(s - 1, 1));

  const commonInputClass = "w-full px-4 py-3 rounded-lg border border-gray-200 bg-[#f4f7f9] text-[#1e293b] font-medium text-[15px] focus:ring-2 focus:ring-orange-primary/20 focus:outline-none transition-all";
