import { supabase } from '../lib/supabase';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

/**
 * Syncs mock data to Supabase. 
 * This attempts to populate your 'schemes' table if it is currently empty.
 */
export const syncMockDataToSupabase = async () => {
  try {
    // 1. Check if the table exists and has data
    const { data: existing, error: checkError } = await supabase
      .from('schemes')
      .select('id')
      .limit(1);

    if (checkError) {
      if (checkError.code === '42P01') {
        console.warn('The "schemes" table does not exist. Please run the SQL setup script in your Supabase Editor.');
      } else {
        console.error('Database connection error:', checkError.message);
      }
      return;
    }

    // 2. If table is empty, insert mock data
    if (!existing || existing.length === 0) {
      console.log('Seeding initial data...');

      // We perform a batch insert. If this fails with RLS error, 
      // it means the user hasn't added the INSERT policy yet.
      const { error: insertError } = await supabase.from('schemes').insert(MOCK_SCHEMES);

      if (insertError) {
        if (insertError.code === '42501') {
          console.error('RLS Violation: The "schemes" table requires an INSERT policy to seed data. Please run the SQL fix.');
        } else {
          console.error('Seeding error:', insertError.message);
        }
      } else {
        console.log('Database successfully seeded with schemes!');
      }
    }
  } catch (err) {
    console.error('Unexpected sync error:', err);
  }
};

export const fetchAllSchemes = async (): Promise<Scheme[]> => {
  try {
    const { data, error } = await supabase
      .from('schemes')
      .select('*')
      .order('updatedAt', { ascending: false });

    // Fallback to MOCK_SCHEMES if there's an error or no data
    if (error || !data || data.length === 0) {
      return MOCK_SCHEMES;
    }
    return (data as Scheme[]);
  } catch (err) {
    return MOCK_SCHEMES;
  }
};

export const fetchSchemeById = async (id: string): Promise<Scheme | null> => {
  try {
    const { data, error } = await supabase
      .from('schemes')
      .select('*')
      .eq('id', id)
      .single();

    if (error) {
      return MOCK_SCHEMES.find(s => s.id === id) || null;
    }
    return (data as Scheme) || null;
  } catch (err) {
    return MOCK_SCHEMES.find(s => s.id === id) || null;
  }
};

import React, { useState } from 'react';
