import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Bookmark, 
  Settings, 
  ArrowRight, 
  Zap, 
  CheckCircle2, 
  Clock, 
  ChevronRight,
  UserCircle
} from 'lucide-react';
import { supabase } from '../lib/supabase';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<any>(null);
  const [savedCount, setSavedCount] = useState(0);

  useEffect(() => {
    const checkAuth = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        navigate('/auth');
        return;
      }

      const { data: profileData } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', session.user.id)
        .single();

      setProfile(profileData || { first_name: session.user.user_metadata?.full_name?.split(' ')[0] || 'User' });

      const saved = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      setSavedCount(saved.length);

      setLoading(false);
    };

    checkAuth();
  }, [navigate]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="w-12 h-12 border-4 border-navy border-t-orange-500 rounded-full animate-spin"></div>
      </div>
    );
  }

  const stats = [
    { label: 'Total Matches', value: '42', icon: <Zap className="text-orange-500" />, color: 'bg-orange-50' },
    { label: 'Saved Schemes', value: savedCount, icon: <Bookmark className="text-blue-500" />, color: 'bg-blue-50' },
    { label: 'Applications', value: '0', icon: <CheckCircle2 className="text-green-500" />, color: 'bg-green-50' },
  ];

  return (
    <div className="min-h-screen bg-[#f9fafb] pb-24">
      <div className="bg-navy pt-20 pb-32">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
            <div className="flex items-center gap-5">
              <div className="w-20 h-20 bg-white/10 backdrop-blur-md rounded-3xl border border-white/20 flex items-center justify-center text-white text-3xl font-bold">
                {profile?.first_name?.[0] || 'U'}
