import React, { useState, useEffect, useRef } from 'react';
import { MessageSquare, X, Send, Bot, Volume2, Languages, Sparkles, Mic, MicOff, Settings2, Check } from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_SCHEMES } from '../constants';

type LanguageOption = {
  name: string;
  code: string;
  voice: string;
  greeting: string;
};

const LANGUAGES: LanguageOption[] = [
  { name: 'English', code: 'en', voice: 'Puck', greeting: 'Hello! How can I help you today?' },
  { name: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपकी कैसे सहायता कर सकता हूँ?' },
  { name: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुम्हाला कशी मदत करू शकतो?' },
  { name: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்களுக்கு எப்படி உதவ முடியும்?' },
  { name: 'తెలుగు', code: 'te', voice: 'Zephyr', greeting: 'నమస్కారం! నేను మీకు ఎలా సహాయపడగలను?' },
];

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showLangMenu, setShowLangMenu] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  // Initialize greeting based on language
  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isOpen, isLoading]);

  // Speech Recognition Setup
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = () => {
        setIsListening(false);
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
      };
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    if (isPlaying) return;
    setIsPlaying(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Speak this in ${selectedLang.name}: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice as any },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const schemeContext = JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description, benefits: s.benefits, eligibility: s.eligibility })));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: `You are the official AI Assistant for Gov-Smart. 
          Website Content: ${schemeContext}. 
          Current Preferred Language: ${selectedLang.name}.
          Rules:
          1. Provide accurate information about government schemes.
          2. ALWAYS respond in ${selectedLang.name} language regardless of user input language, as per user preference.
          3. Keep responses concise and structured.
          4. If a scheme is not in the provided content, mention you can help with general information but advise checking the portal for specifics.
          5. Use a friendly, professional tone.`
        }
      });

      const aiText = response.text || "Service error. Please try again.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service is temporarily busy." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const changeLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowLangMenu(false);
    setMessages(prev => [...prev, { role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end">
      {/* Chat Window */}
      {isOpen && (
        <div className="w-[380px] h-[600px] bg-white rounded-[2.5rem] shadow-2xl border border-gray-100 flex flex-col overflow-hidden mb-4 animate-in fade-in slide-in-from-bottom-4 duration-300">
          {/* Header */}
          <div className="bg-navy p-6 flex flex-col gap-4 relative">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-orange-primary rounded-xl flex items-center justify-center text-white shadow-lg">
                  <Bot size={24} />
                </div>
                <div>
                  <h3 className="text-white font-bold text-sm">Gov-Smart AI</h3>
                  <div className="flex items-center gap-1.5">
                    <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">Multilingual Assistant</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={() => setShowLangMenu(!showLangMenu)} 
                  className={`p-2 rounded-lg transition-all ${showLangMenu ? 'bg-orange-primary text-white' : 'text-gray-400 hover:bg-white/10'}`}
                >
                  <Settings2 size={20} />
                </button>
                <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-lg text-gray-400 transition-all">
                  <X size={20} />
                </button>
              </div>
            </div>

            {/* Language Selection Bar */}
            {showLangMenu && (
              <div className="bg-white/5 backdrop-blur-md rounded-xl p-2 flex flex-wrap gap-2 border border-white/10 animate-in slide-in-from-top-2 duration-200">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => changeLanguage(lang)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 ${
                      selectedLang.code === lang.code 
                      ? 'bg-orange-primary text-white' 
                      : 'bg-white/10 text-gray-300 hover:bg-white/20'
                    }`}
                  >
                    {lang.name}
                    {selectedLang.code === lang.code && <Check size={12} />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-gray-50/50">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in zoom-in duration-200`}>
                <div className={`max-w-[85%] relative ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-4 rounded-2xl text-[15px] leading-relaxed shadow-sm ${
                    msg.role === 'user' 
                    ? 'bg-navy text-white rounded-tr-none' 
                    : 'bg-white text-navy border border-gray-100 rounded-tl-none font-medium'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <button 
                        onClick={() => handleTTS(msg.text)}
                        className={`mt-2 flex items-center gap-1.5 text-[10px] font-black uppercase tracking-wider transition-all px-2 py-1 rounded-lg bg-gray-50 border border-gray-100 ${isPlaying ? 'text-orange-600 animate-pulse' : 'text-gray-500 hover:text-orange-600 hover:bg-orange-50'}`}
                      >
                        <Volume2 size={12} /> {isPlaying ? 'Speaking...' : `Listen in ${selectedLang.name}`}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-4 rounded-2xl rounded-tl-none">
                  <div className="flex gap-1.5">
                    <div className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-1.5 h-1.5 bg-orange-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <form onSubmit={handleSendMessage} className="p-4 bg-white border-t border-gray-100">
            <div className="relative flex items-center gap-2">
              <div className="relative flex-1">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Ask in ${selectedLang.name}...`}
                  // Fixed text visibility with text-navy and font-bold
                  className="w-full pl-4 pr-12 py-4 bg-gray-50 rounded-2xl text-[15px] text-navy font-bold border-2 border-transparent focus:border-orange-200 focus:bg-white focus:outline-none transition-all placeholder:text-gray-400 placeholder:font-medium"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-xl transition-all ${isListening ? 'bg-red-100 text-red-600 animate-pulse' : 'text-gray-400 hover:bg-gray-200 hover:text-navy'}`}
                >
                  {isListening ? <MicOff size={18} /> : <Mic size={18} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                className="p-4 bg-navy text-white rounded-2xl hover:bg-orange-primary transition-all disabled:opacity-50 disabled:scale-95 shadow-lg shadow-navy/10 active:scale-90"
              >
                <Send size={20} />
              </button>
            </div>
            <div className="mt-3 flex items-center justify-center gap-4 text-[10px] text-gray-400 font-bold uppercase tracking-widest">
              <span className="flex items-center gap-1.5"><Languages size={10} /> {selectedLang.name} Active</span>
              <span className="flex items-center gap-1.5 text-orange-500/80"><Sparkles size={10} /> Gemini AI</span>
            </div>
          </form>
        </div>
      )}

      {/* Toggle Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-16 h-16 rounded-full shadow-2xl flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-95 relative group ${isOpen ? 'bg-navy rotate-90' : 'bg-orange-primary'}`}
      >
        <div className="absolute inset-0 rounded-full bg-orange-primary animate-ping opacity-20 group-hover:opacity-0"></div>
        {isOpen ? <X size={28} /> : <MessageSquare size={28} />}
      </button>
    </div>
  );
};

export default ChatWidget;

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Search, Filter, ChevronLeft, ChevronRight, Check, Sparkles, ChevronDown, User as UserIcon } from 'lucide-react';
import { MOCK_SCHEMES, CATEGORIES, INDIAN_STATES_UTS } from '../constants';
import { searchSchemesAI, getAIRecommendations } from '../services/geminiService';
import { UserProfile, Scheme } from '../types';
import { supabase } from '../lib/supabase';

const FindSchemes: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'eligibility' | 'browse'>(searchParams.get('q') || searchParams.get('category') ? 'browse' : 'eligibility');

  // Browsing/Search state
  const [schemes, setSchemes] = useState<Scheme[]>(MOCK_SCHEMES);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState(searchParams.get('q') || '');
  const [selectedCategories, setSelectedCategories] = useState<string[]>(searchParams.get('category') ? [searchParams.get('category')!] : []);
  const [schemeLevel, setSchemeLevel] = useState<string>('All Levels');
  const [isAiFiltered, setIsAiFiltered] = useState(false);

  // Eligibility Wizard state
  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<UserProfile>({
      age: undefined,
      gender: 'Male',
      state: '',
      occupation: '',
      income: '',
      category: 'General' 
  });
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setIsAuthenticated(true);
        // Fetch real profile data from database to auto-fill
        const { data: profileData } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single();

        if (profileData) {
          setProfile({
            age: profileData.age,
            gender: profile.gender, // Gender isn't in current profile table, but we can assume or skip
            state: profileData.state || '',
            occupation: '', // Need to add to profile table if needed
            income: '',
            category: profileData.category || 'General'
          });
        }
      }
    };
    checkUser();
  }, []);

  const isStepValid = () => {
      switch(step) {
          case 1: return !!(profile.age && profile.gender);
          case 2: return !!profile.state;
          case 3: return !!(profile.occupation && profile.income);
          case 4: return true; 
          default: return false;
      }
  };

  useEffect(() => {
    if (activeTab === 'browse' && !isAiFiltered) {
        const performSearch = async () => {
            if (searchQuery) {
                setLoading(true);
                const results = await searchSchemesAI(searchQuery);
                setSchemes(results);
                setLoading(false);
            } else {
                let filtered = MOCK_SCHEMES;
                if (selectedCategories.length > 0) {
                    filtered = filtered.filter(s => selectedCategories.includes(s.category));
                }
                if (schemeLevel !== 'All Levels') {
                    filtered = filtered.filter(s => s.level === schemeLevel);
                }
                setSchemes(filtered);
            }
        };
        const debounce = setTimeout(performSearch, 300);
        return () => clearTimeout(debounce);
    }
  }, [searchQuery, selectedCategories, schemeLevel, activeTab, isAiFiltered]);

  const toggleCategory = (cat: string) => {
    setSelectedCategories(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  const handleFinalSubmit = async () => {
      setLoading(true);
      setActiveTab('browse');
      setIsAiFiltered(true);
      try {
          const recommendations = await getAIRecommendations(profile);
          setSchemes(recommendations);
      } catch (error) {
          console.error("Failed to get recommendations", error);
      } finally {
          setLoading(false);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const nextStep = () => {
    if (step === 4) {
        handleFinalSubmit();
    } else if (isStepValid()) {
        setStep(s => s + 1);
    }
  };

  const prevStep = () => setStep(s => Math.max(s - 1, 1));

  // Added explicit text-[#1e293b] (Navy) for visibility
  const commonInputClass = "w-full px-4 py-3 rounded-lg border border-gray-200 bg-[#f4f7f9] text-[#1e293b] font-bold text-[15px] focus:ring-2 focus:ring-orange-primary/20 focus:outline-none focus:bg-white transition-all placeholder:text-gray-400";
  const commonSelectClass = "w-full px-4 py-3 rounded-lg border border-gray-200 bg-[#f4f7f9] text-[#1e293b] font-bold text-[15px] focus:outline-none focus:bg-white transition-all appearance-none cursor-pointer";

  const renderEligibilityStep = () => {
    switch(step) {
