                            <option value="Student">Student</option>
                            <option value="Self-Employed">Self-Employed</option>
                            <option value="Business Owner">Business Owner</option>
                            <option value="Private Employee">Private Employee</option>
                            <option value="Government Employee">Government Employee</option>
                            <option value="Daily Wage Worker">Daily Wage Worker</option>
                            <option value="Homemaker">Homemaker</option>
                            <option value="Unemployed">Unemployed</option>
                            <option value="Retired">Retired</option>
                        </select>
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                            <ChevronDown size={18} />
                        </div>
                    </div>
                </div>
                <div className="space-y-3">
                    <label className="text-[15px] font-bold text-[#1e293b]">Annual Household Income</label>
                    <div className="relative group">
                        <select 
                            className={commonSelectClass}
                            value={profile.income || ''}
                            onChange={(e) => setProfile({...profile, income: e.target.value})}
                        >
                            <option value="" disabled>Select income bracket</option>
                            <option value="Below ₹1 Lakh">Below ₹1 Lakh</option>
                            <option value="₹1 - 3 Lakhs">₹1 - 3 Lakhs</option>
                            <option value="₹3 - 6 Lakhs">₹3 - 6 Lakhs</option>
                            <option value="Above ₹6 Lakhs">Above ₹6 Lakhs</option>
                        </select>
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                            <ChevronDown size={18} />
                        </div>
                    </div>
                </div>
            </div>
          </div>
        );
      case 4:
        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
                <div>
                    <h2 className="text-[22px] font-bold text-[#1e293b] mb-1">Social Category</h2>
                    <p className="text-gray-500 text-sm">Some schemes have specific eligibility criteria</p>
                </div>
                <div className="pt-2 space-y-3">
                    <label className="block text-[15px] font-bold text-[#1e293b]">Category</label>
                    <div className="relative group">
                        <select 
                            className={commonSelectClass}
                            value={profile.category || ''}
                            onChange={(e) => setProfile({...profile, category: e.target.value})}
                        >
                            <option value="General">General</option>
                            <option value="OBC">OBC</option>
                            <option value="SC">SC</option>
                            <option value="ST">ST</option>
                            <option value="Minority">Minority</option>
                            <option value="EWS">EWS</option>
                        </select>
                        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                            <ChevronDown size={18} />
                        </div>
                    </div>
                </div>
            </div>
        )
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] pb-24 font-sans text-navy">
