                                    'bg-gray-200 text-gray-500'
                                }`}>
                                    {step > s.id ? <Check size={16} strokeWidth={4} /> : s.id}
                                </div>
                                <span className={`text-[13px] font-bold hidden md:block ${step >= s.id ? 'text-[#1e293b]' : 'text-gray-400'}`}>
                                    {s.label}
                                </span>
                            </div>
                            {idx < 3 && <div className="flex-1 h-[1px] bg-gray-200 mx-4 hidden md:block"></div>}
                          </React.Fragment>
                        ))}
                    </div>
                </div>

                <div className="p-8 md:p-12 min-h-[400px]">
                    <div className="max-w-xl">
                        {renderEligibilityStep()}
                    </div>

                    <div className="mt-16 flex justify-between items-center">
                        <button 
                            onClick={prevStep}
                            disabled={step === 1}
                            className={`flex items-center gap-2 text-sm font-bold transition-all px-2 py-1 ${step === 1 ? 'opacity-30 cursor-not-allowed' : 'text-gray-400 hover:text-orange-primary'}`}
                        >
                            <ChevronLeft size={18} /> Back
                        </button>
                        <button 
                            onClick={nextStep}
                            disabled={!isStepValid() && step < 4}
                            className={`flex items-center gap-2 px-8 py-2.5 rounded-lg font-bold text-white transition-all text-sm bg-navy hover:bg-orange-primary shadow-lg ${
                                !isStepValid() && step < 4 ? 'opacity-50 cursor-not-allowed' : ''
                            }`}
                        >
                            {step === 4 ? 'Find Schemes' : 'Continue'} <ChevronRight size={18} />
                        </button>
                    </div>
                </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-12 animate-in fade-in duration-700">
            {/* Sidebar Filters */}
            <div className="lg:col-span-1 space-y-8">
                {isAiFiltered && (
                    <div className="bg-[#1e293b] p-6 rounded-xl shadow-lg text-white">
                        <div className="flex items-center gap-2 text-orange-400 font-bold mb-4 text-xs">
                            <Sparkles size={14} />
                            <span>AI SMART MATCH</span>
                        </div>
                        <p className="text-xs text-gray-300 leading-relaxed mb-6">
                            Recommendations refined for your profile.
                        </p>
                        <button 
                            onClick={() => { setIsAiFiltered(false); setSchemes(MOCK_SCHEMES); }}
                            className="w-full py-2 bg-white/10 hover:bg-orange-primary rounded-lg text-xs font-bold transition-all border border-white/10"
                        >
                            Reset Results
                        </button>
                    </div>
                )}

                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex items-center gap-2 text-[#1e293b] font-bold mb-6 text-sm uppercase tracking-wider">
                        <Filter size={16} className="text-orange-500" />
                        <span>Filter Results</span>
                    </div>

                    <div className="space-y-8">
                        <div>
                            <span className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4 block">Level</span>
                            <div className="space-y-3">
                                {['All Levels', 'Central', 'State'].map((lvl) => (
                                    <label key={lvl} className="flex items-center gap-3 cursor-pointer group">
                                        <div 
                                            onClick={() => setSchemeLevel(lvl)}
                                            className={`w-5 h-5 rounded border transition-all flex items-center justify-center ${schemeLevel === lvl ? 'bg-orange-primary border-orange-primary' : 'border-gray-200 group-hover:border-orange-primary'}`}
                                        >
                                            {schemeLevel === lvl && <Check size={12} className="text-white" strokeWidth={3} />}
                                        </div>
                                        <span className={`text-[13px] font-bold transition-colors ${schemeLevel === lvl ? 'text-orange-primary' : 'text-gray-500 group-hover:text-orange-primary'}`}>{lvl}</span>
                                    </label>
                                ))}
                            </div>
                        </div>

                        <div>
                            <span className="text-[11px] font-bold text-gray-400 uppercase tracking-widest mb-4 block">Categories</span>
                            <div className="space-y-3">
                                {CATEGORIES.map((cat) => (
                                    <label key={cat.label} className="flex items-center gap-3 cursor-pointer group">
                                        <div 
                                            onClick={() => toggleCategory(cat.label)}
                                            className={`w-5 h-5 rounded border transition-all flex items-center justify-center ${selectedCategories.includes(cat.label) ? 'bg-orange-primary border-orange-primary' : 'border-gray-200 group-hover:border-orange-primary'}`}
                                        >
                                            {selectedCategories.includes(cat.label) && <Check size={12} className="text-white" strokeWidth={3} />}
                                        </div>
                                        <span className={`text-[13px] font-bold transition-colors ${selectedCategories.includes(cat.label) ? 'text-orange-primary' : 'text-gray-500 group-hover:text-orange-primary'}`}>{cat.label}</span>
                                    </label>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="lg:col-span-3 space-y-8">
                <div className="relative group">
                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                    <input 
                        type="text" 
                        placeholder="Search schemes..."
                        className="w-full pl-14 pr-4 py-4 rounded-xl border border-gray-100 focus:border-orange-primary focus:outline-none bg-white shadow-sm font-bold text-[#1e293b] text-[15px]"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>

                {loading ? (
                    <div className="flex flex-col items-center justify-center py-24 bg-white rounded-2xl border border-gray-100">
                        <div className="w-12 h-12 border-4 border-gray-100 border-t-orange-500 rounded-full animate-spin mb-4"></div>
                        <p className="text-[#1e293b] font-bold">Matching schemes for you...</p>
                    </div>
                ) : schemes.length > 0 ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        {schemes.map((scheme) => (
                            <div key={scheme.id} className="bg-white rounded-xl p-8 border border-gray-100 hover:border-orange-200 hover:shadow-xl transition-all group flex flex-col h-full">
                                <div className="flex items-center gap-2 mb-4">
                                    <span className="px-3 py-1 bg-green-50 text-green-700 text-[10px] uppercase font-black tracking-widest rounded-md">{scheme.category}</span>
                                    <span className="px-3 py-1 bg-blue-50 text-blue-700 text-[10px] uppercase font-black tracking-widest rounded-md">{scheme.level}</span>
                                </div>
                                <h3 className="text-lg font-bold text-[#1e293b] mb-3 group-hover:text-orange-primary transition-colors line-clamp-2 leading-snug">{scheme.title}</h3>
                                <p className="text-gray-500 text-xs mb-6 flex-grow leading-relaxed line-clamp-3">{scheme.description}</p>
                                <div className="pt-4 border-t border-gray-50">
                                    <button 
                                        onClick={() => navigate(`/scheme/${scheme.id}`)}
                                        className="w-full py-2.5 bg-gray-50 text-[#1e293b] font-bold rounded-lg hover:bg-orange-primary hover:text-white transition-all flex items-center justify-center gap-2 text-sm"
                                    >
                                        View Details <ChevronRight size={16} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="bg-white py-24 px-8 text-center rounded-2xl border border-dashed border-gray-200">
                        <Search className="text-gray-200 mx-auto mb-4" size={48} />
                        <h3 className="text-xl font-bold text-[#1e293b] mb-2">No matching schemes</h3>
                        <p className="text-gray-400 text-sm">Try adjusting your filters.</p>
                    </div>
                )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

