{
  "name": "GOV-Schemes-eligliblity-checker",
  "description": "A comprehensive portal to discover, search, and apply for government welfare schemes across India using AI-driven matching.",
  "requestFramePermissions": [
    "geolocation",
    "microphone"
  ]
}

import React, { useState, useEffect, useRef } from 'react';
import { MessageSquare, X, Send, Bot, Volume2, Languages, Sparkles, Mic, MicOff, Settings2, Check, Globe } from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_SCHEMES } from '../constants';

type LanguageOption = {
  name: string;
  code: string;
  voice: 'Puck' | 'Charon' | 'Kore' | 'Fenrir' | 'Zephyr';
  native: string;
  greeting: string;
};

const LANGUAGES: LanguageOption[] = [
  { name: 'English', native: 'English', code: 'en', voice: 'Puck', greeting: 'Hello! I am your Gov-Smart Assistant. How can I help you today?' },
  { name: 'Hindi', native: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपकी कैसे सहायता कर सकता हूँ?' },
  { name: 'Marathi', native: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुम्हाला कशी मदत करू शकतो?' },
  { name: 'Tamil', native: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்களுக்கு எப்படி உதவ முடியும்?' },
  { name: 'Telugu', native: 'తెలుగు', code: 'te', voice: 'Zephyr', greeting: 'నమస్కారం! నేను మీకు ఎలా సహాయపడగలను?' },
  { name: 'Bengali', native: 'বাংলা', code: 'bn', voice: 'Kore', greeting: 'নমস্কার! আমি আপনাকে কীভাবে সাহায্য করতে পারি?' },
];

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  // Set initial greeting
  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  // Auto-scroll to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading, isOpen]);

  // Speech Recognition Setup
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setInput(transcript);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    if (isPlaying) return;
    setIsPlaying(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Speak this clearly in ${selectedLang.name}: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description, benefits: s.benefits })));

    try {
      // Using gemini-3-flash-preview for fastest possible responses
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are a professional Gov-Smart assistant.
          Context: ${context}.
          User Preference: Speak in ${selectedLang.name} (${selectedLang.native}).
          Instructions:
          1. Answer accurately based on the provided schemes.
          2. ALWAYS respond in ${selectedLang.name}.
          3. Be fast and concise.
          4. If asked about something not in context, answer generally but advise checking official portals.`
        }
      });

      const aiText = response.text || "I'm sorry, I couldn't process that. Try again.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Connection error. Please try again later." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages(prev => [...prev, { role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Main Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[400px] h-[600px] max-h-[80vh] bg-white rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.2)] border border-gray-100 flex flex-col overflow-hidden mb-5 animate-in fade-in slide-in-from-bottom-6 duration-300 pointer-events-auto">
          {/* Header - Advanced UI */}
          <div className="bg-navy p-5 flex flex-col gap-4 relative">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 bg-orange-primary rounded-2xl flex items-center justify-center text-white shadow-lg ring-4 ring-white/5">
                  <Bot size={24} />
                </div>
                <div>
                  <h3 className="text-white font-extrabold text-base leading-tight">Gov Assistant</h3>
                  <div className="flex items-center gap-1.5">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.8)]"></span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Active • {selectedLang.native}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-orange-primary text-white shadow-inner' : 'bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white'}`}
                >
                  <Settings2 size={20} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  className="p-2.5 bg-white/5 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-xl transition-all"
                >
                  <X size={20} />
                </button>
              </div>
            </div>

            {/* Language Selection Grid */}
            {showSettings && (
              <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-3 border border-white/10 grid grid-cols-2 gap-2 animate-in slide-in-from-top-4 fade-in duration-300">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-3 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-between gap-2 ${
                      selectedLang.code === lang.code 
                      ? 'bg-orange-primary text-white shadow-lg' 
                      : 'bg-white/5 text-gray-300 hover:bg-white/10'
                    }`}
                  >
                    <span>{lang.native}</span>
                    {selectedLang.code === lang.code ? <Check size={14} /> : <Globe size={14} className="opacity-30" />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-[#f8fafc]">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in zoom-in-95 duration-200`}>
                <div className={`max-w-[85%] group ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-4 rounded-2xl text-[15px] leading-relaxed shadow-sm transition-transform active:scale-[0.99] ${
                    msg.role === 'user' 
                    ? 'bg-navy text-white rounded-tr-none font-medium' 
                    : 'bg-white text-navy border border-gray-100 rounded-tl-none font-semibold'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <div className="flex gap-2 mt-3">
                        <button 
                          onClick={() => handleTTS(msg.text)}
                          className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-wider px-3 py-1.5 rounded-lg border transition-all ${
                            isPlaying 
                            ? 'bg-orange-50 border-orange-200 text-orange-600 animate-pulse' 
                            : 'bg-gray-50 border-gray-100 text-gray-400 hover:bg-orange-50 hover:border-orange-200 hover:text-orange-600'
                          }`}
                        >
                          <Volume2 size={12} /> {isPlaying ? 'Speaking...' : `Listen (${selectedLang.name})`}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-5 rounded-2xl rounded-tl-none shadow-sm">
                  <div className="flex gap-2">
                    <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce"></div>
                    <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* User Input - High Visibility Fixed */}
          <div className="p-4 bg-white border-t border-gray-100">
            <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
              <div className="relative flex-1 group">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Type in ${selectedLang.name}...`}
                  // ABSOLUTE FIX: text-navy font-bold for max visibility
                  className="w-full pl-4 pr-12 py-4 bg-gray-50 border-2 border-transparent rounded-[1.25rem] text-[16px] text-navy font-bold focus:bg-white focus:border-orange-primary focus:outline-none transition-all placeholder:text-gray-400 placeholder:font-medium shadow-inner"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-xl transition-all ${
                    isListening 
                    ? 'bg-red-500 text-white shadow-lg animate-pulse' 
                    : 'text-gray-400 hover:bg-gray-200 hover:text-navy'
                  }`}
                  title="Speech to Text"
                >
                  {isListening ? <MicOff size={20} /> : <Mic size={20} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                className="w-14 h-14 bg-navy text-white rounded-2xl flex items-center justify-center hover:bg-orange-primary hover:scale-105 active:scale-90 transition-all shadow-xl shadow-navy/20 disabled:opacity-50 disabled:scale-100 disabled:hover:bg-navy"
              >
                <Send size={24} />
              </button>
            </form>
            <div className="mt-3 flex items-center justify-between px-1">
              <div className="flex items-center gap-1.5 text-[9px] text-gray-400 font-black uppercase tracking-widest">
                <Languages size={10} /> {selectedLang.name} Assistant
              </div>
              <div className="flex items-center gap-1 text-[9px] text-orange-500/80 font-black uppercase tracking-widest">
                <Sparkles size={10} /> Powered by Gemini 3 Flash
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Floating Action Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-16 h-16 sm:w-18 sm:h-18 rounded-[2rem] shadow-[0_10px_40px_rgba(249,115,22,0.3)] flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-95 pointer-events-auto relative group ${
          isOpen ? 'bg-navy rotate-90 scale-90' : 'bg-orange-primary'
        }`}
      >
        <div className="absolute inset-0 rounded-[2rem] bg-orange-primary animate-ping opacity-15 group-hover:opacity-0"></div>
        {isOpen ? <X size={32} /> : <MessageSquare size={32} />}
      </button>
    </div>
  );
};

