const LANGUAGES: LanguageOption[] = [
  { name: 'English', native: 'English', code: 'en', voice: 'Puck', greeting: 'Hello! I am your Gov-Smart Assistant. How can I help you today?' },
  { name: 'Hindi', native: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपकी कैसे सहायता कर सकता हूँ?' },
  { name: 'Marathi', native: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुम्हाला कशी मदत करू शकतो?' },
  { name: 'Tamil', native: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்களுக்கு எப்படி உதவ முடியும்?' },
  { name: 'Telugu', native: 'తెలుగు', code: 'te', voice: 'Zephyr', greeting: 'నమస్కారం! నేను మీకు ఎలా సహాయపడగలను?' },
  { name: 'Bengali', native: 'বাংলা', code: 'bn', voice: 'Kore', greeting: 'নমস্কার! আমি আপনাকে কীভাবে সাহায্য করতে পারি?' },
];

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  // Set initial greeting
  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  // Auto-scroll to bottom
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading, isOpen]);

  // Speech Recognition Setup
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setInput(transcript);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    if (isPlaying) return;
    setIsPlaying(true);

    // Initialize AudioContext immediately to reduce perceived delay
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      // Prompt optimized for speed
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description, benefits: s.benefits, eligibility: s.eligibility })));

    try {
      // Improved instruction for accuracy and politeness
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the official Gov-Smart AI Assistant. Your goal is to provide 99% accurate information about government schemes.

Context (Use this for schemes): ${context}.
Language: You MUST respond in ${selectedLang.name} (${selectedLang.native}).

Behavioral Rules:
1. GREETINGS: If the user says 'Hi', 'Hello', 'Namaste', or similar, respond warmly. Example: "Hello! I am your Gov-Smart Assistant. How can I help you today?"
2. ACCURACY: Provide extremely specific and accurate details from the context.
3. STRUCTURE: Use short sentences and clear points.
4. OUT-OF-CONTEXT: If the user asks something unrelated to welfare schemes, politely redirect them back to government programs.
5. TONE: Professional, helpful, and polite.
6. SPEED: Be concise to ensure quick responses.`
        }
      });

      const aiText = response.text || "I'm sorry, I encountered an error. Could you please repeat that?";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service temporarily busy. Please try again in a few seconds." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages(prev => [...prev, { role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Main Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[400px] h-[600px] max-h-[85vh] bg-white rounded-[2.5rem] shadow-[0_25px_60px_rgba(0,0,0,0.25)] border border-gray-100 flex flex-col overflow-hidden mb-5 animate-in fade-in slide-in-from-bottom-6 duration-300 pointer-events-auto">
          {/* Header */}
          <div className="bg-navy p-5 flex flex-col gap-4 relative">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-11 h-11 bg-orange-primary rounded-2xl flex items-center justify-center text-white shadow-lg ring-4 ring-white/5">
                  <Bot size={24} />
                </div>
                <div>
                  <h3 className="text-white font-extrabold text-base leading-tight">Gov Assistant</h3>
                  <div className="flex items-center gap-1.5">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.8)]"></span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Active • {selectedLang.native}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-orange-primary text-white shadow-inner' : 'bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white'}`}
                >
                  <Settings2 size={20} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  className="p-2.5 bg-white/5 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-xl transition-all"
                >
                  <X size={20} />
                </button>
              </div>
            </div>

            {/* Language Selection Grid */}
            {showSettings && (
              <div className="bg-white/10 backdrop-blur-2xl rounded-2xl p-3 border border-white/10 grid grid-cols-2 gap-2 animate-in slide-in-from-top-4 fade-in duration-300">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-3 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-between gap-2 ${
                      selectedLang.code === lang.code 
                      ? 'bg-orange-primary text-white shadow-lg' 
                      : 'bg-white/10 text-gray-300 hover:bg-white/20'
                    }`}
                  >
                    <span>{lang.native}</span>
                    {selectedLang.code === lang.code ? <Check size={14} /> : <Globe size={14} className="opacity-30" />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 bg-[#f8fafc]">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in zoom-in-95 duration-200`}>
                <div className={`max-w-[88%] group ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-4 rounded-2xl text-[15px] leading-relaxed shadow-sm transition-transform active:scale-[0.99] ${
                    msg.role === 'user' 
                    ? 'bg-navy text-white rounded-tr-none font-medium' 
                    : 'bg-white text-navy border border-gray-100 rounded-tl-none font-semibold'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <div className="flex gap-2 mt-3">
                        <button 
                          onClick={() => handleTTS(msg.text)}
                          className={`flex items-center gap-1.5 text-[10px] font-black uppercase tracking-wider px-3 py-1.5 rounded-lg border transition-all ${
                            isPlaying 
                            ? 'bg-orange-100 border-orange-300 text-orange-700 animate-pulse' 
                            : 'bg-gray-50 border-gray-100 text-gray-500 hover:bg-orange-50 hover:border-orange-200 hover:text-orange-600'
                          }`}
                        >
                          <Volume2 size={12} /> {isPlaying ? 'Speaking...' : `Listen in ${selectedLang.name}`}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-5 rounded-2xl rounded-tl-none shadow-sm">
                  <div className="flex gap-2">
                    <div className="w-2.5 h-2.5 bg-orange-400 rounded-full animate-bounce"></div>
                    <div className="w-2.5 h-2.5 bg-orange-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-2.5 h-2.5 bg-orange-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* User Input Area */}
          <div className="p-4 bg-white border-t border-gray-100">
            <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
              <div className="relative flex-1 group">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Type in ${selectedLang.name}...`}
                  className="w-full pl-4 pr-12 py-4 bg-gray-50 border-2 border-transparent rounded-[1.25rem] text-[16px] text-navy font-bold focus:bg-white focus:border-orange-primary focus:outline-none transition-all placeholder:text-gray-400 placeholder:font-medium shadow-inner"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-xl transition-all ${
                    isListening 
                    ? 'bg-red-500 text-white shadow-lg animate-pulse' 
                    : 'text-gray-400 hover:bg-gray-200 hover:text-navy'
                  }`}
                  title="Speech to Text"
                >
                  {isListening ? <MicOff size={20} /> : <Mic size={20} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                className="w-14 h-14 bg-navy text-white rounded-2xl flex items-center justify-center hover:bg-orange-primary hover:scale-105 active:scale-90 transition-all shadow-xl shadow-navy/20 disabled:opacity-50 disabled:scale-100 disabled:hover:bg-navy"
              >
                <Send size={24} />
              </button>
            </form>
            <div className="mt-3 flex items-center justify-center px-1">
              <div className="flex items-center gap-1.5 text-[10px] text-gray-400 font-black uppercase tracking-widest">
                <Languages size={11} /> {selectedLang.name} Assistant Active
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Floating Action Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-16 h-16 sm:w-18 sm:h-18 rounded-[2rem] shadow-[0_12px_45px_rgba(249,115,22,0.4)] flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-95 pointer-events-auto relative group ${
          isOpen ? 'bg-navy rotate-90 scale-90' : 'bg-orange-primary'
        }`}
      >
        <div className="absolute inset-0 rounded-[2rem] bg-orange-primary animate-ping opacity-15 group-hover:opacity-0"></div>
        {isOpen ? <X size={32} /> : <MessageSquare size={32} />}
      </button>
    </div>
  );
};

export default ChatWidget;

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Search, Filter, ChevronLeft, ChevronRight, Check, Sparkles, ChevronDown, User as UserIcon, Loader2 } from 'lucide-react';
import { MOCK_SCHEMES, CATEGORIES, INDIAN_STATES_UTS } from '../constants';
import { searchSchemesAI, getAIRecommendations } from '../services/geminiService';
import { UserProfile, Scheme } from '../types';
import { supabase } from '../lib/supabase';

const FindSchemes: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'eligibility' | 'browse'>(searchParams.get('q') || searchParams.get('category') ? 'browse' : 'eligibility');

  const [schemes, setSchemes] = useState<Scheme[]>(MOCK_SCHEMES);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState(searchParams.get('q') || '');
  const [selectedCategories, setSelectedCategories] = useState<string[]>(searchParams.get('category') ? [searchParams.get('category')!] : []);
  const [schemeLevel, setSchemeLevel] = useState<string>('All Levels');
  const [isAiFiltered, setIsAiFiltered] = useState(false);

  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<UserProfile>({
      age: undefined,
      gender: 'Male',
      state: '',
      occupation: '',
      income: '',
      category: 'General' 
  });
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setIsAuthenticated(true);
        const { data: profileData } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', session.user.id)
          .single();

        if (profileData) {
          setProfile({
            age: profileData.age,
            gender: 'Male', 
            state: profileData.state || '',
            occupation: '',
            income: '',
            category: profileData.category || 'General'
          });
        }
      }
    };
    checkUser();
  }, []);

  const isStepValid = () => {
      switch(step) {
          case 1: return !!(profile.age && profile.gender);
          case 2: return !!profile.state;
          case 3: return !!(profile.occupation && profile.income);
          case 4: return true; 
          default: return false;
      }
  };

  useEffect(() => {
    if (activeTab === 'browse' && !isAiFiltered) {
        const performSearch = async () => {
            setLoading(true);
            if (searchQuery) {
                const results = await searchSchemesAI(searchQuery);
                setSchemes(results);
            } else {
                let filtered = MOCK_SCHEMES;
                if (selectedCategories.length > 0) {
                    filtered = filtered.filter(s => selectedCategories.includes(s.category));
                }
                if (schemeLevel !== 'All Levels') {
                    filtered = filtered.filter(s => s.level === schemeLevel);
                }
                setSchemes(filtered);
            }
            setLoading(false);
        };
        const debounce = setTimeout(performSearch, 400);
        return () => clearTimeout(debounce);
    }
  }, [searchQuery, selectedCategories, schemeLevel, activeTab, isAiFiltered]);

  const toggleCategory = (cat: string) => {
    setSelectedCategories(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  const handleFinalSubmit = async () => {
      setLoading(true);
      setActiveTab('browse');
      setIsAiFiltered(true);
      try {
          const recommendations = await getAIRecommendations(profile);
          setSchemes(recommendations);
      } catch (error) {
          console.error("Failed to get recommendations", error);
      } finally {
          setLoading(false);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const nextStep = () => {
    if (step === 4) {
        handleFinalSubmit();
    } else if (isStepValid()) {
        setStep(s => s + 1);
    }
  };

  const prevStep = () => setStep(s => Math.max(s - 1, 1));

  const commonInputClass = "w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 text-navy font-bold text-[16px] focus:ring-4 focus:ring-orange-primary/10 focus:border-orange-primary/20 focus:outline-none focus:bg-white transition-all placeholder:text-gray-400 shadow-inner";
  const commonSelectClass = "w-full px-5 py-4 rounded-2xl border border-gray-100 bg-gray-50 text-navy font-bold text-[16px] focus:outline-none focus:bg-white transition-all appearance-none cursor-pointer shadow-inner";

  const renderEligibilityStep = () => {
    switch(step) {
      case 1:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
            <div>
              <h2 className="text-2xl font-extrabold text-navy mb-2">Personal Details</h2>
              <p className="text-gray-500 text-sm font-medium">Help us find schemes suitable for you</p>
            </div>
            {isAuthenticated && (
              <div className="bg-orange-50 p-4 rounded-2xl border border-orange-100 flex items-center gap-3">
                <UserIcon className="text-orange-500" size={20} />
                <span className="text-sm font-bold text-orange-700 tracking-tight">Using data from your profile settings.</span>
              </div>
            )}
            <div className="space-y-6 pt-4">
              <div className="space-y-3">
                <label className="text-sm font-black text-gray-400 uppercase tracking-widest">Your Age</label>
                <input 
                  type="number" 
                  placeholder="e.g. 19"
                  className={commonInputClass}
                  value={profile.age || ''}
                  onChange={(e) => setProfile({...profile, age: parseInt(e.target.value) || undefined})}
                />
              </div>
              <div className="space-y-3">
                <label className="text-sm font-black text-gray-400 uppercase tracking-widest">Gender</label>
                <div className="flex flex-wrap items-center gap-4 pt-1">
                  {['Male', 'Female', 'Other'].map((g) => (
                    <button 
                      key={g} 
                      type="button"
                      onClick={() => setProfile({...profile, gender: g as any})}
                      className={`px-6 py-3 rounded-xl font-bold text-sm transition-all border-2 ${
                        profile.gender === g 
                        ? 'bg-navy border-navy text-white shadow-lg' 
                        : 'bg-white border-gray-100 text-gray-500 hover:border-orange-primary hover:text-orange-primary'
                      }`}
                    >
                      {g}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );
      case 2:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
            <div>
              <h2 className="text-2xl font-extrabold text-navy mb-2">Location</h2>
              <p className="text-gray-500 text-sm font-medium">Tell us which state you belong to</p>
            </div>
            <div className="pt-4 space-y-3">
                <label className="text-sm font-black text-gray-400 uppercase tracking-widest">State / UT</label>
                <div className="relative group">
                    <select 
                        className={commonSelectClass}
                        value={profile.state || ''}
                        onChange={(e) => setProfile({...profile, state: e.target.value})}
                    >
                        <option value="" disabled>Select your state</option>
                        {INDIAN_STATES_UTS.map(state => (
                          <option key={state} value={state}>{state}</option>
                        ))}
                    </select>
                    <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <ChevronDown size={20} />
                    </div>
                </div>
            </div>
          </div>
        );
      case 3:
        return (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
            <div>
              <h2 className="text-2xl font-extrabold text-navy mb-2">Income & Work</h2>
              <p className="text-gray-500 text-sm font-medium">This helps in matching financial aid programs</p>
            </div>
            <div className="space-y-6 pt-4">
                <div className="space-y-3">
                    <label className="text-sm font-black text-gray-400 uppercase tracking-widest">Occupation</label>
                    <div className="relative group">
                        <select 
                            className={commonSelectClass}
                            value={profile.occupation || ''}
                            onChange={(e) => setProfile({...profile, occupation: e.target.value})}
                        >
                            <option value="" disabled>Select occupation</option>
                            <option value="Farmer">Farmer</option>
                            <option value="Student">Student</option>
                            <option value="Self-Employed">Self-Employed</option>
                            <option value="Private Employee">Private Employee</option>
                            <option value="Daily Wage Worker">Daily Wage Worker</option>
                            <option value="Unemployed">Unemployed</option>
                        </select>
                        <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                            <ChevronDown size={20} />
                        </div>
                    </div>
                </div>
                <div className="space-y-3">
                    <label className="text-sm font-black text-gray-400 uppercase tracking-widest">Household Income</label>
                    <div className="relative group">
                        <select 
                            className={commonSelectClass}
                            value={profile.income || ''}
                            onChange={(e) => setProfile({...profile, income: e.target.value})}
                        >
                            <option value="" disabled>Select income bracket</option>
                            <option value="Below ₹1 Lakh">Below ₹1 Lakh</option>
                            <option value="₹1 - 3 Lakhs">₹1 - 3 Lakhs</option>
                            <option value="Above ₹3 Lakhs">Above ₹3 Lakhs</option>
