import React, { useState, useEffect, useRef } from 'react';
import { MessageSquare, X, Send, Bot, Volume2, Languages, Mic, MicOff, Settings2, Check, Globe, Loader2 } from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_SCHEMES } from '../constants';

type LanguageOption = {
  name: string;
  code: string;
  voice: 'Puck' | 'Charon' | 'Kore' | 'Fenrir' | 'Zephyr';
  native: string;
  greeting: string;
};

const LANGUAGES: LanguageOption[] = [
  { name: 'English', native: 'English', code: 'en', voice: 'Puck', greeting: 'Hello! I am your Gov-Smart Assistant. How can I help you today?' },
  { name: 'Hindi', native: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपकी कैसे सहायता कर सकता हूँ?' },
  { name: 'Marathi', native: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुम्हाला कशी मदत करू शकतो?' },
  { name: 'Tamil', native: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்களுக்கு எப்படி உதவ முடியும்?' },
  { name: 'Telugu', native: 'తెలుగు', code: 'te', voice: 'Zephyr', greeting: 'నమస్కారం! నేను మీకు ఎలా సహాయపడగలను?' },
  { name: 'Bengali', native: 'বাংলা', code: 'bn', voice: 'Kore', greeting: 'নমস্কার! আমি আপনাকে কীভাবে সাহায্য করতে পারি?' },
];

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading, isOpen]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setInput(transcript);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    if (isPlaying) return;
    setIsPlaying(true);

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description, benefits: s.benefits, eligibility: s.eligibility })));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the official Gov-Smart AI Assistant. You provide highly accurate information about government schemes.

Context: ${context}.
Language Preference: Respond in ${selectedLang.name} (${selectedLang.native}).

Guidelines:
1. Warm Greetings: If user says 'Hi' or 'Namaste', respond warmly in their language.
2. Accuracy: Only provide info from the context provided.
3. Concise: Be very fast and clear.
4. Professional: Stay polite and helpful.
5. Out-of-Context: Gently redirect users if they ask non-government questions.`
        }
      });

      const aiText = response.text || "I apologize, I'm having trouble processing that right now.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service is temporarily busy. Please try again." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages(prev => [...prev, { role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none group/widget">
      {/* Improved Responsive Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[420px] h-[650px] max-h-[85vh] bg-white rounded-[2.5rem] shadow-[0_30px_80px_rgba(0,0,0,0.3)] border border-gray-100 flex flex-col overflow-hidden mb-6 animate-in fade-in slide-in-from-bottom-8 duration-500 pointer-events-auto">
          {/* Header - Navy & Orange Theme */}
          <div className="bg-navy p-6 flex flex-col gap-4 relative shadow-lg z-10">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-orange-primary rounded-2xl flex items-center justify-center text-white shadow-[0_8px_20px_rgba(249,115,22,0.4)] ring-4 ring-white/5 transform hover:scale-105 transition-transform">
                  <Bot size={28} strokeWidth={2.5} />
                </div>
                <div>
                  <h3 className="text-white font-black text-lg leading-tight tracking-tight">Assistant</h3>
                  <div className="flex items-center gap-2">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_12px_rgba(34,197,94,0.8)]"></span>
                    <span className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Live • {selectedLang.native}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  className={`p-3 rounded-2xl transition-all ${showSettings ? 'bg-orange-primary text-white shadow-inner' : 'bg-white/10 text-gray-400 hover:bg-white/20 hover:text-white'}`}
                >
                  <Settings2 size={22} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  className="p-3 bg-white/5 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-2xl transition-all"
                >
                  <X size={22} />
                </button>
              </div>
            </div>

            {/* Language Selection Grid - Polished */}
            {showSettings && (
              <div className="bg-white/10 backdrop-blur-3xl rounded-[1.5rem] p-3 border border-white/10 grid grid-cols-2 gap-2 animate-in slide-in-from-top-4 fade-in duration-300">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-3 py-3 rounded-xl text-[11px] font-black uppercase tracking-wider transition-all flex items-center justify-between gap-2 ${
                      selectedLang.code === lang.code 
                      ? 'bg-orange-primary text-white shadow-lg scale-[1.02]' 
                      : 'bg-white/10 text-gray-300 hover:bg-white/20'
                    }`}
                  >
                    <span>{lang.native}</span>
                    {selectedLang.code === lang.code ? <Check size={14} strokeWidth={3} /> : <Globe size={14} className="opacity-20" />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Optimized Message Area */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 bg-[#f8fafc] scroll-smooth">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in zoom-in-95 duration-300`}>
                <div className={`max-w-[88%] group ${msg.role === 'user' ? 'order-2' : ''}`}>
