import React, { useState, useEffect, useRef } from 'react';
import { MessageSquare, X, Send, Bot, Volume2, Languages, Mic, MicOff, Settings2, Check, Globe, Loader2, Sparkles } from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_SCHEMES } from '../constants';

type LanguageOption = {
  name: string;
  code: string;
  voice: 'Puck' | 'Charon' | 'Kore' | 'Fenrir' | 'Zephyr';
  native: string;
  greeting: string;
};

const LANGUAGES: LanguageOption[] = [
  { name: 'English', native: 'English', code: 'en', voice: 'Puck', greeting: 'Hello! I am your Gov-Smart Assistant. How can I help you today?' },
  { name: 'Hindi', native: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपकी कैसे सहायता कर सकता हूँ?' },
  { name: 'Marathi', native: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुम्हाला कशी मदत करू शकतो?' },
  { name: 'Tamil', native: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்களுக்கு எப்படி உதவ முடியும்?' },
  { name: 'Telugu', native: 'తెలుగు', code: 'te', voice: 'Zephyr', greeting: 'నమస్కారం! నేను మీకు ఎలా సహాయపడగలను?' },
  { name: 'Bengali', native: 'বাংলা', code: 'bn', voice: 'Kore', greeting: 'নমস্কার! আমি আপনাকে কীভাবে সাহায্য করতে পারি?' },
];

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);

  // Initialize with greeting
  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  // Auto-scroll logic
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading, isOpen]);

  // Voice recognition setup
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setInput(transcript);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    if (isPlaying) return;
    setIsPlaying(true);

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description, benefits: s.benefits, eligibility: s.eligibility })));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the official Gov-Smart AI Assistant. You provide highly accurate info about government schemes.

Context (Schemes Available): ${context}.
Output Language: You MUST respond in ${selectedLang.name} (${selectedLang.native}).

Guidelines:
1. GREETINGS: If user says 'Hi', 'Hello', 'Namaste', respond warmly. E.g., "Hello! I am your Gov-Smart Assistant. How can I help you today?"
2. ACCURACY: Provide 99% accurate details based ONLY on the provided context.
3. CONCISE: Keep answers clear and formatted with bullet points if possible.
4. OUT-OF-CONTEXT: If asked about non-scheme topics, politely redirect.
5. NO BRANDING: Do not mention Gemini or AI models in the text output.`
        }
      });

      const aiText = response.text || "I apologize, I'm having trouble processing that right now.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service is temporarily busy. Please try again." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages([{ role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Refined Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-32px)] sm:w-[440px] h-[680px] max-h-[85vh] bg-white rounded-[3rem] shadow-[0_40px_100px_rgba(0,0,0,0.35)] border border-gray-100 flex flex-col overflow-hidden mb-6 animate-in fade-in slide-in-from-bottom-12 duration-500 pointer-events-auto">

          {/* Custom Header */}
          <div className="bg-[#1e293b] p-7 flex flex-col gap-5 relative z-20 shadow-xl">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-14 h-14 bg-[#f97316] rounded-2xl flex items-center justify-center text-white shadow-[0_8px_25px_rgba(249,115,22,0.4)] ring-4 ring-white/10 transform transition-transform hover:scale-105">
                  <Bot size={32} strokeWidth={2.5} />
                </div>
                <div>
                  <h3 className="text-white font-black text-xl leading-tight tracking-tight">AI Assistant</h3>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="w-2.5 h-2.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.8)]"></span>
                    <span className="text-[11px] text-gray-400 font-black uppercase tracking-[0.25em]">Online • {selectedLang.native}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  aria-label="Settings"
                  className={`p-3.5 rounded-2xl transition-all ${showSettings ? 'bg-[#f97316] text-white shadow-inner' : 'bg-white/10 text-gray-400 hover:bg-white/20 hover:text-white'}`}
                >
                  <Settings2 size={24} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  aria-label="Close"
                  className="p-3.5 bg-white/5 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-2xl transition-all"
                >
                  <X size={24} />
                </button>
              </div>
            </div>

            {/* Language Selection Grid */}
            {showSettings && (
              <div className="bg-white/10 backdrop-blur-3xl rounded-[2rem] p-4 border border-white/10 grid grid-cols-2 gap-3 animate-in slide-in-from-top-4 fade-in duration-300">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-4 py-3.5 rounded-2xl text-[12px] font-black uppercase tracking-widest transition-all flex items-center justify-between gap-3 ${
                      selectedLang.code === lang.code 
                      ? 'bg-[#f97316] text-white shadow-xl scale-[1.03]' 
                      : 'bg-white/10 text-gray-300 hover:bg-white/20'
                    }`}
                  >
                    <span>{lang.native}</span>
                    {selectedLang.code === lang.code ? <Check size={16} strokeWidth={3} /> : <Globe size={16} className="opacity-20" />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Optimized Chat Area */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-7 space-y-10 bg-[#f8fafc] scroll-smooth scrollbar-hide">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in zoom-in-95 duration-400`}>
                <div className={`max-w-[90%] relative ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-6 rounded-[2rem] text-[16px] leading-relaxed shadow-sm transition-all relative ${
                    msg.role === 'user' 
                    ? 'bg-[#1e293b] text-white rounded-tr-none font-bold' 
                    : 'bg-white text-[#1e293b] border border-gray-100 rounded-tl-none font-bold'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <div className="flex gap-3 mt-5">
                        <button 
                          onClick={() => handleTTS(msg.text)}
                          className={`flex items-center gap-2.5 text-[11px] font-black uppercase tracking-[0.2em] px-5 py-2.5 rounded-2xl border-2 transition-all ${
                            isPlaying 
                            ? 'bg-orange-100 border-orange-300 text-orange-700 animate-pulse' 
                            : 'bg-gray-50 border-gray-100 text-gray-400 hover:bg-orange-50 hover:border-orange-200 hover:text-orange-600'
                          }`}
                        >
                          <Volume2 size={16} /> {isPlaying ? 'Speaking...' : `Speak (${selectedLang.code})`}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-8 rounded-[2rem] rounded-tl-none shadow-sm flex items-center gap-3">
                  <div className="flex gap-2">
                    <div className="w-3 h-3 bg-[#f97316] rounded-full animate-bounce"></div>
                    <div className="w-3 h-3 bg-[#f97316] rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-3 h-3 bg-[#f97316] rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Premium Input Bar */}
          <div className="p-6 bg-white border-t border-gray-100 shadow-[0_-15px_50px_rgba(0,0,0,0.03)] relative z-20">
            <form onSubmit={handleSendMessage} className="relative flex items-center gap-4">
              <div className="relative flex-1 group">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Speak or type in ${selectedLang.name}...`}
                  className="w-full pl-6 pr-16 py-5 bg-gray-50 border-2 border-transparent rounded-[2rem] text-[17px] text-[#1e293b] font-black focus:bg-white focus:border-[#f97316]/30 focus:outline-none transition-all placeholder:text-gray-300 placeholder:font-black shadow-inner"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  aria-label="Voice Input"
                  className={`absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-2xl transition-all ${
                    isListening 
                    ? 'bg-red-500 text-white shadow-[0_0_20px_rgba(239,68,68,0.6)] animate-pulse' 
                    : 'text-gray-400 hover:bg-gray-200 hover:text-[#1e293b]'
                  }`}
                >
                  {isListening ? <MicOff size={24} /> : <Mic size={24} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                aria-label="Send Message"
                className="w-16 h-16 bg-[#1e293b] text-white rounded-[1.5rem] flex items-center justify-center hover:bg-[#f97316] hover:scale-105 active:scale-95 transition-all shadow-2xl shadow-[#1e293b]/20 disabled:opacity-30 disabled:scale-100 disabled:hover:bg-[#1e293b]"
              >
                {isLoading ? <Loader2 size={28} className="animate-spin" /> : <Send size={28} strokeWidth={2.5} />}
              </button>
            </form>
            <div className="mt-5 flex items-center justify-center gap-6">
              <div className="flex items-center gap-2.5 text-[11px] text-gray-400 font-black uppercase tracking-[0.25em]">
                <Languages size={14} className="text-[#f97316]" /> {selectedLang.name} Mode
              </div>
              <div className="flex items-center gap-2.5 text-[11px] text-gray-400 font-black uppercase tracking-[0.25em]">
                <Sparkles size={14} className="text-[#f97316]" /> High Accuracy
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Main Floating Action Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        aria-label={isOpen ? "Close Chat" : "Open Chat"}
        className={`w-20 h-20 sm:w-22 sm:h-22 rounded-[2.5rem] shadow-[0_20px_60px_rgba(249,115,22,0.5)] flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-90 pointer-events-auto relative group ${
          isOpen ? 'bg-[#1e293b] rotate-90 scale-90' : 'bg-[#f97316]'
        }`}
      >
        <div className="absolute inset-0 rounded-[2.5rem] bg-[#f97316] animate-ping opacity-25 group-hover:opacity-0 transition-opacity"></div>
        {isOpen ? <X size={40} strokeWidth={2.5} /> : <MessageSquare size={40} strokeWidth={2.5} />}
      </button>
    </div>
  );
};

