  }, [messages, isLoading, isOpen]);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setInput(transcript);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    if (isPlaying) return;
    setIsPlaying(true);

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();
      } else {
        setIsPlaying(false);
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ title: s.title, desc: s.description, benefits: s.benefits, eligibility: s.eligibility })));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the professional and polite Gov-Smart Assistant.

Context: ${context}.
Output Language: Always respond in ${selectedLang.name} (${selectedLang.native}).

Personality & Rules:
1. POLITENESS: Always greet the user warmly if they say hi/hello. Respond with: "Hi! How can I help you today?" or similar in ${selectedLang.name}.
2. ACCURACY: Provide 99% accurate information about government schemes from the context.
3. STRUCTURE: Use clear, short sentences or bullet points.
4. OUT-OF-CONTEXT: If a user asks a question not related to schemes or welfare, politely ask if they would like to know about government programs instead.
5. NO AI BRANDING: Never mention Gemini, Flash, or Google in your responses.`
        }
      });

      const aiText = response.text || "I'm sorry, I couldn't process that. Please try again.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service temporarily unavailable. Please try again shortly." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages([{ role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Properly Oriented Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[380px] h-[580px] max-h-[82vh] bg-white rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.2)] border border-gray-100 flex flex-col overflow-hidden mb-5 animate-in fade-in slide-in-from-bottom-4 duration-300 pointer-events-auto">
          {/* Header */}
          <div className="bg-navy p-5 flex flex-col gap-4 relative shadow-md">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-orange-primary rounded-xl flex items-center justify-center text-white shadow-lg">
                  <Bot size={22} strokeWidth={2.5} />
                </div>
                <div>
                  <h3 className="text-white font-bold text-base tracking-tight">Gov Assistant</h3>
                  <div className="flex items-center gap-1.5">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.6)]"></span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{selectedLang.native}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  className={`p-2 rounded-lg transition-all ${showSettings ? 'bg-orange-primary text-white' : 'text-gray-400 hover:bg-white/10 hover:text-white'}`}
                >
                  <Settings2 size={18} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  className="p-2 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-lg transition-all"
                >
                  <X size={18} />
                </button>
              </div>
            </div>

            {/* Language Selector */}
            {showSettings && (
              <div className="bg-white/5 backdrop-blur-md rounded-xl p-2 border border-white/10 grid grid-cols-2 gap-2 animate-in slide-in-from-top-2 fade-in duration-200">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-3 py-2 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-all flex items-center justify-between ${
                      selectedLang.code === lang.code 
                      ? 'bg-orange-primary text-white shadow-md' 
                      : 'bg-white/5 text-gray-300 hover:bg-white/10'
                    }`}
                  >
                    {lang.native}
                    {selectedLang.code === lang.code && <Check size={12} strokeWidth={3} />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-6 bg-[#f8fafc]">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in duration-300`}>
                <div className={`max-w-[85%] ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-4 rounded-2xl text-[14px] leading-relaxed shadow-sm ${
                    msg.role === 'user' 
                    ? 'bg-navy text-white rounded-tr-none font-medium' 
                    : 'bg-white text-navy border border-gray-100 rounded-tl-none font-medium'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <button 
                        onClick={() => handleTTS(msg.text)}
                        className={`flex items-center gap-1.5 mt-3 text-[9px] font-black uppercase tracking-wider px-2 py-1 rounded-md border transition-all ${
                          isPlaying 
                          ? 'bg-orange-50 border-orange-200 text-orange-600' 
                          : 'bg-gray-50 border-gray-100 text-gray-400 hover:text-orange-600'
                        }`}
                      >
                        <Volume2 size={12} /> {isPlaying ? 'Speaking...' : 'Listen'}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-4 rounded-2xl rounded-tl-none shadow-sm flex gap-1.5">
                  <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 bg-white border-t border-gray-100">
            <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
              <div className="relative flex-1">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Ask about schemes...`}
                  className="w-full pl-4 pr-10 py-3 bg-gray-50 border border-transparent rounded-xl text-[14px] text-navy font-bold focus:bg-white focus:border-orange-primary/30 focus:outline-none transition-all placeholder:text-gray-300"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  className={`absolute right-2 top-1/2 -translate-y-1/2 p-1.5 rounded-lg transition-all ${
                    isListening ? 'bg-red-500 text-white shadow-md' : 'text-gray-400 hover:text-navy'
                  }`}
                >
                  {isListening ? <MicOff size={16} /> : <Mic size={16} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                className="w-10 h-10 bg-navy text-white rounded-xl flex items-center justify-center hover:bg-orange-primary transition-all disabled:opacity-50"
              >
                {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Send size={18} />}
              </button>
            </form>
            <div className="mt-3 flex items-center justify-center gap-3">
              <div className="flex items-center gap-1 text-[9px] text-gray-400 font-bold uppercase tracking-widest">
                <Languages size={10} className="text-orange-500" /> {selectedLang.name}
              </div>
              <div className="flex items-center gap-1 text-[9px] text-gray-400 font-bold uppercase tracking-widest">
                <Sparkles size={10} className="text-orange-500" /> 99% Accuracy
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Floating Action Button - Corrected Size */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-14 h-14 rounded-2xl shadow-xl flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-90 pointer-events-auto relative ${
          isOpen ? 'bg-navy rotate-90' : 'bg-orange-primary'
        }`}
      >
        <div className="absolute inset-0 rounded-2xl bg-orange-primary animate-ping opacity-10"></div>
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </button>
    </div>
  );
};

