    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ 
      title: s.title, 
      desc: s.description, 
      benefits: s.benefits, 
      eligibility: s.eligibility 
    })));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the professional and polite Gov-Smart Assistant. 
          Respond ONLY based on the following website content about government schemes: ${context}.
          Always respond in ${selectedLang.name} (${selectedLang.native}).

          Guidelines:
          1. GREETINGS: If user says hi/hello, greet them warmly in their language.
          2. ACCURACY: Provide 99% accurate details. If information is missing, say you don't know but suggest they check official portals.
          3. TONE: Be helpful and respectful.
          4. NO BRANDING: Do not mention AI models or Gemini in your output.`
        }
      });

      const aiText = response.text || "I'm sorry, I couldn't process that.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service busy. Please try again." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages(prev => [...prev, { role: 'ai', text: lang.greeting }]);
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Compact Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[360px] h-[550px] max-h-[80vh] bg-white rounded-2xl shadow-2xl border border-gray-100 flex flex-col overflow-hidden mb-5 animate-in fade-in slide-in-from-bottom-4 duration-300 pointer-events-auto">
          {/* Header */}
          <div className="bg-navy p-4 flex flex-col gap-3 relative shadow-md">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-orange-primary rounded-lg flex items-center justify-center text-white">
                  <Bot size={20} strokeWidth={2.5} />
                </div>
                <div>
                  <h3 className="text-white font-bold text-sm tracking-tight">Gov Assistant</h3>
                  <div className="flex items-center gap-1">
                    <span className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></span>
                    <span className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">{selectedLang.native}</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  className={`p-1.5 rounded-lg transition-all ${showSettings ? 'bg-orange-primary text-white' : 'text-gray-400 hover:bg-white/10'}`}
                >
                  <Settings2 size={16} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  className="p-1.5 text-gray-400 hover:bg-white/10 rounded-lg transition-all"
                >
                  <X size={16} />
                </button>
              </div>
            </div>

            {/* Language Picker Overlay */}
            {showSettings && (
              <div className="bg-white/5 backdrop-blur-md rounded-xl p-1.5 border border-white/10 grid grid-cols-2 gap-1 animate-in slide-in-from-top-2 duration-200">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-2 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-wider transition-all flex items-center justify-between ${
                      selectedLang.code === lang.code ? 'bg-orange-primary text-white' : 'text-gray-300 hover:bg-white/10'
                    }`}
                  >
                    {lang.native}
                    {selectedLang.code === lang.code && <Check size={10} strokeWidth={3} />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-5 bg-[#f8fafc]">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in duration-300`}>
                <div className={`max-w-[85%] ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-3.5 rounded-2xl text-[13px] leading-relaxed shadow-sm ${
                    msg.role === 'user' 
                    ? 'bg-navy text-white rounded-tr-none font-bold' 
                    : 'bg-white text-navy border border-gray-100 rounded-tl-none font-bold'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <button 
                        onClick={() => handleTTS(msg.text)}
                        className={`flex items-center gap-1 mt-2 text-[8px] font-black uppercase tracking-wider transition-all ${
                          isPlaying ? 'text-orange-500 animate-pulse' : 'text-gray-400 hover:text-orange-500'
                        }`}
                      >
                        <Volume2 size={12} /> {isPlaying ? 'Playing...' : 'Listen'}
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-3 rounded-2xl rounded-tl-none shadow-sm flex gap-1">
                  <div className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce"></div>
                  <div className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-300 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-3 bg-white border-t border-gray-100">
            <form onSubmit={handleSendMessage} className="relative flex items-center gap-2">
              <div className="relative flex-1">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Type or Speak...`}
                  className="w-full pl-3 pr-10 py-2.5 bg-gray-50 border border-transparent rounded-xl text-[13px] text-navy font-bold focus:bg-white focus:border-orange-primary/30 focus:outline-none transition-all placeholder:text-gray-300"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  className={`absolute right-2 top-1/2 -translate-y-1/2 p-1.5 rounded-lg transition-all ${
                    isListening ? 'bg-red-500 text-white shadow-md' : 'text-gray-400 hover:text-navy'
                  }`}
                >
                  {isListening ? <MicOff size={14} /> : <Mic size={14} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                className="w-9 h-9 bg-navy text-white rounded-lg flex items-center justify-center hover:bg-orange-primary transition-all disabled:opacity-50"
              >
                {isLoading ? <Loader2 size={16} className="animate-spin" /> : <Send size={16} />}
              </button>
            </form>
            <div className="mt-2 flex items-center justify-center gap-3">
              <div className="flex items-center gap-1 text-[8px] text-gray-400 font-bold uppercase tracking-widest">
                <Globe size={10} className="text-orange-500" /> {selectedLang.name}
              </div>
              <div className="flex items-center gap-1 text-[8px] text-gray-400 font-bold uppercase tracking-widest">
                <Sparkles size={10} className="text-orange-500" /> AI Grounded
              </div>
            </div>
          </div>
        </div>
      )}

      {/* FAB - Corrected Size & Reverted Logic */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-14 h-14 rounded-2xl shadow-xl flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-90 pointer-events-auto relative ${
          isOpen ? 'bg-navy rotate-90' : 'bg-orange-primary'
        }`}
      >
        <div className="absolute inset-0 rounded-2xl bg-orange-primary animate-ping opacity-10 pointer-events-none"></div>
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </button>
    </div>
  );
};

