    // If we are currently playing THIS exact message, stop it.
    if (isPlaying && currentTtsTextRef.current === text) {
      if (audioSourceRef.current) {
        try {
          audioSourceRef.current.stop();
        } catch (e) {}
        audioSourceRef.current = null;
      }
      setIsPlaying(false);
      currentTtsTextRef.current = null;
      return;
    }

    // If we are playing something else, stop that first.
    if (audioSourceRef.current) {
      try {
        audioSourceRef.current.stop();
      } catch (e) {}
      audioSourceRef.current = null;
    }

    setIsPlaying(true);
    currentTtsTextRef.current = text;

    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);

        source.onended = () => {
          if (currentTtsTextRef.current === text) {
            setIsPlaying(false);
            currentTtsTextRef.current = null;
          }
        };

        audioSourceRef.current = source;
        source.start();
      } else {
        setIsPlaying(false);
        currentTtsTextRef.current = null;
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
      currentTtsTextRef.current = null;
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ 
      title: s.title, 
      desc: s.description, 
      benefits: s.benefits, 
      eligibility: s.eligibility 
    })));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the professional Gov-Smart Assistant.

          Context for Schemes: ${context}.
          Target Language: ${selectedLang.name} (${selectedLang.native}).

          Strict Rules:
          1. GREETING: If user says "hi", "hello", "namaste", etc., ALWAYS respond with: "Hi! How can I help you today?" (translated into ${selectedLang.name}).
          2. ACCURACY: Provide 99% accurate information based only on the provided context. 
          3. RELEVANCE: If asked about non-scheme topics, politely redirect to government welfare programs.
          4. FORMATTING: Use bold text for key terms and bullet points for lists.
          5. NO BRANDING: Never mention Gemini, AI models, or Google.
          6. SPEED: Respond concisely and directly.`
        }
      });

      const aiText = response.text || "I'm sorry, I'm having trouble processing that right now.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service temporarily busy. Please try again." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages([{ role: 'ai', text: lang.greeting }]);
    // Stop any current audio
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e){}
      audioSourceRef.current = null;
      setIsPlaying(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Properly Oriented and Responsive Chat Window */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[380px] h-[600px] max-h-[82vh] bg-white rounded-3xl shadow-[0_20px_60px_rgba(0,0,0,0.15)] border border-gray-100 flex flex-col overflow-hidden mb-5 animate-in fade-in slide-in-from-bottom-4 duration-300 pointer-events-auto">
          {/* Header */}
          <div className="bg-navy p-5 flex flex-col gap-4 relative shadow-lg z-10">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-orange-primary rounded-xl flex items-center justify-center text-white shadow-lg shadow-orange-500/20">
                  <Bot size={24} strokeWidth={2.5} />
                </div>
                <div>
                  <h3 className="text-white font-black text-base tracking-tight leading-none">AI Assistant</h3>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.6)]"></span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{selectedLang.native} • Online</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1.5">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  aria-label="Language Settings"
                  className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-orange-primary text-white' : 'text-gray-400 hover:bg-white/10 hover:text-white'}`}
                >
                  <Settings2 size={18} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  aria-label="Close Chat"
                  className="p-2.5 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-xl transition-all"
                >
                  <X size={18} />
                </button>
              </div>
            </div>

            {/* Language Settings Drawer */}
            {showSettings && (
              <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-2 border border-white/10 grid grid-cols-2 gap-2 animate-in slide-in-from-top-2 fade-in duration-200">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-3 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex items-center justify-between gap-2 ${
                      selectedLang.code === lang.code 
                      ? 'bg-orange-primary text-white shadow-md' 
                      : 'bg-white/5 text-gray-300 hover:bg-white/10'
                    }`}
                  >
                    <span>{lang.native}</span>
                    {selectedLang.code === lang.code && <Check size={12} strokeWidth={3} />}
