              </div>
              <div className="flex items-center gap-1.5 text-[9px] text-gray-400 font-black uppercase tracking-[0.2em]">
                <Sparkles size={11} className="text-orange-primary" /> 99% Accuracy
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Floating Action Button - Reverted to Proper Size */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        aria-label={isOpen ? "Close AI Assistant" : "Open AI Assistant"}
        className={`w-14 h-14 sm:w-16 sm:h-16 rounded-2xl shadow-2xl flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-90 pointer-events-auto relative group ${
          isOpen ? 'bg-navy rotate-90' : 'bg-orange-primary'
        }`}
      >
        <div className="absolute inset-0 rounded-2xl bg-orange-primary animate-ping opacity-10 group-hover:opacity-0 pointer-events-none"></div>
        {isOpen ? <X size={28} strokeWidth={3} /> : <MessageSquare size={28} strokeWidth={3} />}
      </button>
    </div>
  );
};

export default ChatWidget;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { MessageSquare, X, Send, Bot, Volume2, Mic, MicOff, Settings2, Check, Globe, Loader2, Sparkles, VolumeX } from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { MOCK_SCHEMES } from '../constants';

type LanguageOption = {
  name: string;
  code: string;
  voice: 'Puck' | 'Charon' | 'Kore' | 'Fenrir' | 'Zephyr';
  native: string;
  greeting: string;
};

const LANGUAGES: LanguageOption[] = [
  { name: 'English', native: 'English', code: 'en', voice: 'Puck', greeting: 'Hello! I am your Gov-Smart Assistant. How can I help you today?' },
  { name: 'Hindi', native: 'हिन्दी', code: 'hi', voice: 'Kore', greeting: 'नमस्ते! मैं आपकी कैसे सहायता कर सकता हूँ?' },
  { name: 'Marathi', native: 'मराठी', code: 'mr', voice: 'Kore', greeting: 'नमस्कार! मी तुम्हाला कशी मदत करू शकतो?' },
  { name: 'Tamil', native: 'தமிழ்', code: 'ta', voice: 'Zephyr', greeting: 'வணக்கம்! நான் உங்களுக்கு எப்படி உதவ முடியும்?' },
  { name: 'Telugu', native: 'తెలుగు', code: 'te', voice: 'Zephyr', greeting: 'నమస్కారం! నేను మీకు ఎలా సహాయపడగలను?' },
  { name: 'Bengali', native: 'বাংলা', code: 'bn', voice: 'Kore', greeting: 'নমস্কার! আমি আপনাকে কীভাবে সাহায্য করতে পারি?' },
];

const ChatWidget: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [selectedLang, setSelectedLang] = useState<LanguageOption>(LANGUAGES[0]);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const recognitionRef = useRef<any>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const currentTtsTextRef = useRef<string | null>(null);

  // Memoize AI instance for minor performance boost (though guidelines recommend fresh instances for Live/Veo, 
  // for standard chat content it's fine here to keep it ready)
  const aiClient = useMemo(() => new GoogleGenAI({ apiKey: process.env.API_KEY }), []);

  // Initialize with greeting
  useEffect(() => {
    if (messages.length === 0) {
      setMessages([{ role: 'ai', text: selectedLang.greeting }]);
    }
  }, []);

  // Auto-scroll logic
  useEffect(() => {
    if (scrollRef.current && isOpen) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isLoading, isOpen]);

  // Voice recognition setup (Web Speech API)
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = true;
      recognitionRef.current.lang = selectedLang.code === 'en' ? 'en-IN' : `${selectedLang.code}-IN`;

      recognitionRef.current.onresult = (event: any) => {
        const transcript = Array.from(event.results)
          .map((result: any) => result[0])
          .map((result: any) => result.transcript)
          .join('');
        setInput(transcript);
      };

      recognitionRef.current.onerror = () => setIsListening(false);
      recognitionRef.current.onend = () => setIsListening(false);
    }
  }, [selectedLang]);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
    } else {
      setIsListening(true);
      recognitionRef.current?.start();
    }
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleTTS = async (text: string) => {
    // TOGGLE LOGIC: If currently playing this text, stop it.
    if (isPlaying && currentTtsTextRef.current === text) {
      if (audioSourceRef.current) {
        try { audioSourceRef.current.stop(); } catch (e) {}
        audioSourceRef.current = null;
      }
      setIsPlaying(false);
      currentTtsTextRef.current = null;
      return;
    }

    // Stop any other active speaker
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch (e) {}
      audioSourceRef.current = null;
    }

    setIsPlaying(true);
    currentTtsTextRef.current = text;

    // Initialize AudioContext on first interaction
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    try {
      // Use the faster 2.5 series for TTS as per guidelines
      const response = await aiClient.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: selectedLang.voice },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);

        source.onended = () => {
          if (currentTtsTextRef.current === text) {
            setIsPlaying(false);
            currentTtsTextRef.current = null;
          }
        };

        audioSourceRef.current = source;
        source.start();
      } else {
        setIsPlaying(false);
        currentTtsTextRef.current = null;
      }
    } catch (error) {
      console.error("TTS Error:", error);
      setIsPlaying(false);
      currentTtsTextRef.current = null;
    }
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userQuery = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userQuery }]);
    setIsLoading(true);

    const context = JSON.stringify(MOCK_SCHEMES.map(s => ({ 
      title: s.title, 
      desc: s.description, 
      benefits: s.benefits, 
      eligibility: s.eligibility 
    })));

    try {
      const response = await aiClient.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: `You are the professional, friendly, and efficient Gov-Smart Assistant.

          Knowledge Base (Schemes): ${context}.
          Response Language: ${selectedLang.name} (${selectedLang.native}).

          Response Guidelines:
          1. GREETING: If the user says "hi", "hello", "hey", or equivalent, ALWAYS respond with: "Hi! How can I help you today?" (translated correctly).
          2. CONCISENESS: Keep answers short and direct to reduce latency.
          3. ACCURACY: Provide 99% accurate details based ONLY on the provided knowledge base.
          4. REDIRECTION: If a user asks something irrelevant to government schemes, politely bring them back to the topic.
          5. NO BRANDING: Do not mention Google, Gemini, or being an AI model. Just act as the portal assistant.`
        }
      });

      const aiText = response.text || "I apologize, I am unable to process that. Please try again.";
      setMessages(prev => [...prev, { role: 'ai', text: aiText }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "I'm experiencing high traffic. Please try again in a moment." }]);
    } finally {
      setIsLoading(false);
    }
  };

  const selectLanguage = (lang: LanguageOption) => {
    setSelectedLang(lang);
    setShowSettings(false);
    setMessages([{ role: 'ai', text: lang.greeting }]);
    if (audioSourceRef.current) {
      try { audioSourceRef.current.stop(); } catch(e){}
      audioSourceRef.current = null;
      setIsPlaying(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[9999] flex flex-col items-end pointer-events-none">
      {/* Optimized Orientation & Responsive UI */}
      {isOpen && (
        <div className="w-[calc(100vw-48px)] sm:w-[380px] h-[600px] max-h-[82vh] bg-white rounded-3xl shadow-[0_20px_60px_rgba(0,0,0,0.15)] border border-gray-100 flex flex-col overflow-hidden mb-5 animate-in fade-in slide-in-from-bottom-4 duration-300 pointer-events-auto">
          {/* Header */}
          <div className="bg-navy p-5 flex flex-col gap-4 relative shadow-lg z-10">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-orange-primary rounded-xl flex items-center justify-center text-white shadow-lg shadow-orange-500/20">
                  <Bot size={24} strokeWidth={2.5} />
                </div>
                <div>
                  <h3 className="text-white font-black text-base tracking-tight leading-none">AI Assistant</h3>
                  <div className="flex items-center gap-1.5 mt-1">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(34,197,94,0.6)]"></span>
                    <span className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{selectedLang.native} • Online</span>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-1.5">
                <button 
                  onClick={() => setShowSettings(!showSettings)}
                  aria-label="Language"
                  className={`p-2.5 rounded-xl transition-all ${showSettings ? 'bg-orange-primary text-white' : 'text-gray-400 hover:bg-white/10 hover:text-white'}`}
                >
                  <Settings2 size={18} />
                </button>
                <button 
                  onClick={() => setIsOpen(false)} 
                  aria-label="Close"
                  className="p-2.5 text-gray-400 hover:bg-red-500/20 hover:text-red-400 rounded-xl transition-all"
                >
                  <X size={18} />
                </button>
              </div>
            </div>

            {/* Language Selector */}
            {showSettings && (
              <div className="bg-white/5 backdrop-blur-xl rounded-2xl p-2 border border-white/10 grid grid-cols-2 gap-2 animate-in slide-in-from-top-2 duration-200">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => selectLanguage(lang)}
                    className={`px-3 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all flex items-center justify-between gap-2 ${
                      selectedLang.code === lang.code ? 'bg-orange-primary text-white shadow-md' : 'bg-white/5 text-gray-300 hover:bg-white/10'
                    }`}
                  >
                    <span>{lang.native}</span>
                    {selectedLang.code === lang.code && <Check size={12} strokeWidth={3} />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Chat History */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-8 bg-[#f8fafc] scroll-smooth">
            {messages.map((msg, idx) => (
              <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in zoom-in-95 duration-300`}>
                <div className={`max-w-[88%] relative ${msg.role === 'user' ? 'order-2' : ''}`}>
                  <div className={`p-4 rounded-2xl text-[14.5px] leading-relaxed shadow-sm transition-all ${
                    msg.role === 'user' ? 'bg-navy text-white rounded-tr-none font-bold' : 'bg-white text-navy border border-gray-100 rounded-tl-none font-bold'
                  }`}>
                    {msg.text}
                    {msg.role === 'ai' && (
                      <div className="flex gap-2 mt-4">
                        <button 
                          onClick={() => handleTTS(msg.text)}
                          className={`flex items-center gap-1.5 text-[9px] font-black uppercase tracking-[0.15em] px-3 py-1.5 rounded-lg border transition-all ${
                            (isPlaying && currentTtsTextRef.current === msg.text)
                            ? 'bg-orange-50 border-orange-200 text-orange-600 animate-pulse' 
                            : 'bg-gray-50 border-gray-100 text-gray-400 hover:bg-orange-50 hover:border-orange-200 hover:text-orange-600'
                          }`}
                        >
                          {(isPlaying && currentTtsTextRef.current === msg.text) ? <VolumeX size={13} /> : <Volume2 size={13} />} 
                          {(isPlaying && currentTtsTextRef.current === msg.text) ? 'Stop' : 'Listen'}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white border border-gray-100 p-5 rounded-2xl rounded-tl-none shadow-sm flex gap-2">
                  <div className="w-2.5 h-2.5 bg-orange-primary rounded-full animate-bounce"></div>
                  <div className="w-2.5 h-2.5 bg-orange-primary rounded-full animate-bounce [animation-delay:0.2s]"></div>
                  <div className="w-2.5 h-2.5 bg-orange-primary rounded-full animate-bounce [animation-delay:0.4s]"></div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area - High Visibility */}
          <div className="p-5 bg-white border-t border-gray-100">
            <form onSubmit={handleSendMessage} className="relative flex items-center gap-3">
              <div className="relative flex-1">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={`Speak or type in ${selectedLang.name}...`}
                  className="w-full pl-5 pr-12 py-4 bg-gray-50 border-2 border-transparent rounded-2xl text-[15px] text-navy font-bold focus:bg-white focus:border-orange-primary/30 focus:outline-none transition-all placeholder:text-gray-300"
                />
                <button 
                  type="button"
                  onClick={toggleListening}
                  className={`absolute right-3 top-1/2 -translate-y-1/2 p-2 rounded-xl transition-all ${
                    isListening ? 'bg-red-500 text-white shadow-lg animate-pulse' : 'text-gray-400 hover:bg-gray-200 hover:text-navy'
                  }`}
                >
                  {isListening ? <MicOff size={18} /> : <Mic size={18} />}
                </button>
              </div>
              <button 
                type="submit"
                disabled={!input.trim() || isLoading}
                className="w-12 h-12 bg-navy text-white rounded-[1rem] flex items-center justify-center hover:bg-orange-primary hover:scale-105 active:scale-95 transition-all shadow-xl disabled:opacity-30"
              >
                {isLoading ? <Loader2 size={22} className="animate-spin" /> : <Send size={22} strokeWidth={2.5} />}
              </button>
            </form>
            <div className="mt-4 flex items-center justify-center gap-5">
              <div className="flex items-center gap-1.5 text-[9px] text-gray-400 font-black uppercase tracking-[0.2em]">
                <Globe size={11} className="text-orange-primary" /> {selectedLang.name}
              </div>
              <div className="flex items-center gap-1.5 text-[9px] text-gray-400 font-black uppercase tracking-[0.2em]">
                <Sparkles size={11} className="text-orange-primary" /> Verified Info
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Reverted FAB size for better usability */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-14 h-14 sm:w-16 sm:h-16 rounded-2xl shadow-2xl flex items-center justify-center text-white transition-all transform hover:scale-110 active:scale-90 pointer-events-auto relative group ${
          isOpen ? 'bg-navy rotate-90' : 'bg-orange-primary'
        }`}
      >
        <div className="absolute inset-0 rounded-2xl bg-orange-primary animate-ping opacity-10 group-hover:opacity-0 pointer-events-none"></div>
        {isOpen ? <X size={28} strokeWidth={3} /> : <MessageSquare size={28} strokeWidth={3} />}
      </button>
    </div>
  );
};

