            <Link to="/" className="flex items-center gap-3">
              <div className="bg-navy p-2 rounded-xl shadow-lg shadow-navy/10">
                <span className="text-white font-black text-xl tracking-tighter">GS</span>
              </div>
              <div className="hidden sm:block">
                <span className="text-navy font-bold text-xl block leading-tight">Gov-Smart</span>
                <span className="text-[10px] text-orange-500 font-bold uppercase tracking-wider block">AI-Powered Portal</span>
              </div>
            </Link>
          </div>

          <div className="hidden lg:flex flex-1 justify-center">
            <div className="flex items-center gap-x-10">
              {navLinks.map((link) => (
                <Link 
                  key={link.path}
                  to={link.path} 
                  className={`relative py-2 text-sm font-bold transition-all duration-300 ${
                    isActive(link.path) 
                    ? 'text-navy' 
                    : 'text-gray-400 hover:text-navy'
                  }`}
                >
                  {link.name}
                  {isActive(link.path) && (
                    <span className="absolute bottom-0 left-0 w-full h-0.5 bg-orange-primary rounded-full animate-in fade-in zoom-in duration-300"></span>
                  )}
                </Link>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-x-6">
            <div className="hidden md:flex items-center gap-x-6 pr-6 border-r border-gray-100">
              <button className="text-gray-400 hover:text-navy transition-colors">
                <Search size={20} />
              </button>
            </div>

            {user ? (
              <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="flex items-center gap-2 p-1 bg-gray-50 rounded-full border border-gray-200 hover:border-orange-200 transition-all hover:bg-white group overflow-hidden"
                >
                  <div className="relative w-9 h-9 bg-navy rounded-full flex items-center justify-center text-white">
                    <User size={18} />
                    <div className="absolute -bottom-0.5 -right-0.5 w-3 h-3 bg-green-500 rounded-full border-2 border-white shadow-sm"></div>
                  </div>
                  <ChevronDown size={14} className={`text-gray-400 mx-1.5 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
                </button>

                {isProfileOpen && (
                  <div className="absolute right-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-5 bg-gray-50/50 border-b border-gray-100">
                      <p className="text-sm font-bold text-navy truncate">{userDisplayName}</p>
                      <p className="text-xs text-gray-400 truncate">{user.email}</p>
                    </div>
                    <div className="p-2">
                      <Link to="/dashboard" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-navy rounded-xl transition-all">
                        <LayoutDashboard size={18} /> Dashboard
                      </Link>
                      <Link to="/saved" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-navy rounded-xl transition-all">
                        <Bookmark size={18} /> Saved Schemes
                      </Link>
                      <Link to="/settings" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-semibold text-gray-600 hover:bg-gray-50 hover:text-navy rounded-xl transition-all">
                        <Settings size={18} /> Profile Settings
                      </Link>
                      <hr className="my-2 border-gray-100" />
                      <button 
                        onClick={handleLogout}
                        className="w-full flex items-center gap-3 px-4 py-3 text-sm font-semibold text-red-500 hover:bg-red-50 rounded-xl transition-all"
                      >
                        <LogOut size={18} /> Sign Out
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <Link 
                to="/auth" 
                className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-navy text-white hover:bg-orange-primary font-bold text-sm rounded-xl transition-all duration-300 shadow-md shadow-navy/10"
              >
                <User size={18} />
                <span>Sign In</span>
              </Link>
            )}

            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="lg:hidden p-2 rounded-xl hover:bg-gray-100 text-navy transition-all"
            >
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      <div 
        className={`lg:hidden overflow-hidden transition-all duration-300 ease-in-out bg-white border-t border-gray-50 ${
          isMenuOpen ? 'max-h-[500px] opacity-100' : 'max-h-0 opacity-0'
        }`}
      >
        <div className="px-4 py-6 space-y-4">
          {navLinks.map((link) => (
            <Link 
              key={link.path}
              to={link.path}
              onClick={() => setIsMenuOpen(false)}
              className={`flex items-center justify-between p-4 rounded-2xl font-bold transition-all ${
                isActive(link.path) 
                ? 'bg-orange-50 text-orange-600' 
                : 'text-navy hover:bg-gray-50'
              }`}
            >
              {link.name}
              <ChevronRight size={18} className={isActive(link.path) ? 'opacity-100' : 'opacity-0'} />
            </Link>
          ))}
          <div className="pt-4 border-t border-gray-50">
            {user ? (
               <button 
                onClick={handleLogout}
                className="w-full flex items-center justify-center gap-2 p-4 bg-red-50 text-red-500 rounded-2xl font-bold hover:bg-red-100 transition-all"
              >
                <LogOut size={18} /> Sign Out
              </button>
            ) : (
              <Link 
                to="/auth"
                onClick={() => setIsMenuOpen(false)}
                className="w-full flex items-center justify-center gap-2 p-4 bg-navy text-white rounded-2xl font-bold hover:bg-orange-primary transition-all shadow-xl"
              >
                <User size={18} />
                Sign In to Your Account
              </Link>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { Mail, Lock, Sparkles, ChevronLeft, Eye, EyeOff, UserCircle, CheckCircle2 } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';

const Auth: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const navigate = useNavigate();

  // Form states
  const [formData, setFormData] = useState({
    email: '',
    username: '',
    password: '',
    confirmPassword: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleAuthAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    // Mock validation
    if (!isLogin && formData.password !== formData.confirmPassword) {
      setError("Passwords do not match");
      setLoading(false);
      return;
    }

    try {
      // Mock network delay
      await new Promise(resolve => setTimeout(resolve, 800));

      if (isLogin) {
        // Mock Login
        const mockUser = {
          email: formData.email,
          username: formData.email.split('@')[0],
          id: 'mock-uuid-' + Date.now()
        };
        localStorage.setItem('gov_smart_user', JSON.stringify(mockUser));
        window.dispatchEvent(new Event('storage'));
        navigate('/');
      } else {
        // Mock Register
        const mockUser = {
          email: formData.email,
          username: formData.username || formData.email.split('@')[0],
          id: 'mock-uuid-' + Date.now()
        };
        localStorage.setItem('gov_smart_user', JSON.stringify(mockUser));
        setSuccess("Your account is created successfully!");
        window.dispatchEvent(new Event('storage'));
        setTimeout(() => {
            navigate('/');
        }, 1500);
      }
    } catch (err: any) {
      setError('An error occurred. Please try again.');
    } finally {
      if (!success) setLoading(false);
    }
  };

  const labelClass = "text-[14px] font-bold text-[#1e293b]";
  const commonInputClass = "w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/5 focus:outline-none bg-white text-[15px] text-[#1e293b] font-medium placeholder:text-gray-400 transition-all";

  return (
    <div className="min-h-screen bg-[#f9fafb] flex flex-col items-center pt-8 pb-24 px-4 font-sans">
      <div className="w-full max-w-[460px] mb-8">
        <Link 
          to="/" 
          className="inline-flex items-center gap-2 text-[15px] font-bold text-gray-400 hover:text-[#1e293b] transition-all group"
        >
          <div className="w-8 h-8 rounded-full bg-white border border-gray-100 flex items-center justify-center shadow-sm group-hover:shadow transition-all">
            <ChevronLeft size={18} />
          </div>
          <span>Back to Home</span>
        </Link>
      </div>

      <div className="w-full max-w-[460px]">
        <div className="text-center mb-8 flex flex-col items-center">
            <div className="bg-[#1e293b] w-16 h-16 rounded-full flex items-center justify-center mb-5 shadow-sm">
                <Sparkles className="text-white" size={32} />
            </div>
            <h1 className="text-3xl font-bold text-[#1e293b] tracking-tight">Gov-Smart</h1>
            <p className="text-gray-500 text-[15px] mt-1">AI-Powered Schemes Portal</p>
        </div>

        <div className="bg-white rounded-3xl shadow-2xl shadow-navy/5 border border-gray-100 w-full overflow-hidden">
          <div className="flex p-1.5 bg-gray-50/80 m-6 rounded-2xl border border-gray-100">
            <button 
              type="button"
              onClick={() => { setIsLogin(true); setError(null); setSuccess(null); }}
              className={`flex-1 py-3 text-[15px] font-bold transition-all rounded-xl ${
                isLogin 
                ? 'bg-white text-[#1e293b] shadow-sm ring-1 ring-black/5' 
                : 'text-gray-400 hover:text-gray-700'
              }`}
            >
              Sign In
            </button>
            <button 
              type="button"
              onClick={() => { setIsLogin(false); setError(null); setSuccess(null); }}
              className={`flex-1 py-3 text-[15px] font-bold transition-all rounded-xl ${
                !isLogin 
                ? 'bg-white text-[#1e293b] shadow-sm ring-1 ring-black/5' 
                : 'text-gray-400 hover:text-gray-700'
              }`}
            >
              Create Account
            </button>
          </div>

          <form onSubmit={handleAuthAction} className="px-8 md:px-12 pb-12 pt-4">
            {error && (
              <div className="mb-8 p-4 bg-red-50 border border-red-100 text-red-600 text-sm rounded-2xl font-bold animate-in fade-in slide-in-from-top-2">
                {error}
              </div>
            )}

            {success && (
              <div className="mb-8 p-4 bg-green-50 border border-green-100 text-green-700 text-sm rounded-2xl font-bold flex items-center gap-2 animate-in fade-in slide-in-from-top-2">
                <CheckCircle2 size={18} />
                {success}
              </div>
            )}

            <div className="space-y-6">
              {!isLogin && (
                <div className="space-y-2">
                  <label className={labelClass}>Username</label>
                  <div className="relative">
                    <UserCircle className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="username" required placeholder="yourname"
                      value={formData.username} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>
              )}

              <div className="space-y-2">
                <label className={labelClass}>Email Address</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    type="email" name="email" required placeholder="name@example.com"
                    value={formData.email} onChange={handleChange} className={commonInputClass}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label className={labelClass}>Password</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                  <input 
                    type={showPassword ? "text" : "password"} name="password" required placeholder="••••••••"
                    value={formData.password} onChange={handleChange} className={commonInputClass}
                  />
                  <button 
                    type="button" onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-[#1e293b]"
                  >
                    {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                  </button>
                </div>
              </div>

              {!isLogin && (
                <div className="space-y-2">
                  <label className={labelClass}>Confirm Password</label>
                  <div className="relative">
                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type={showPassword ? "text" : "password"} name="confirmPassword" required placeholder="••••••••"
                      value={formData.confirmPassword} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>
              )}
            </div>

            <button 
              type="submit"
              disabled={loading}
              className="w-full py-4 bg-[#1e293b] hover:bg-orange-primary text-white font-bold rounded-2xl shadow-xl shadow-navy/10 transition-all flex items-center justify-center mt-10 text-[16px] disabled:opacity-50"
            >
              {loading ? 'Processing...' : (isLogin ? 'Sign In' : 'Create Account')}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { User, MapPin, Calendar, Tag, Save, ChevronLeft, Sparkles, Loader2 } from 'lucide-react';
import { useNavigate, Link } from 'react-router-dom';
import { INDIAN_STATES_UTS } from '../constants';

const Settings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);
  const [user, setUser] = useState<any>(null);

  const [profile, setProfile] = useState({
    first_name: '',
    last_name: '',
    street_address: '',
    city: '',
    state: '',
    age: '',
    category: 'General'
  });

  useEffect(() => {
    const checkAuth = () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }
      const parsedUser = JSON.parse(savedUser);
      setUser(parsedUser);

      const savedProfile = localStorage.getItem(`profile_${parsedUser.id}`);
      if (savedProfile) {
        setProfile(JSON.parse(savedProfile));
      } else {
        setProfile({
          first_name: parsedUser.username || '',
          last_name: '',
          street_address: '',
          city: '',
          state: '',
          age: '',
          category: 'General'
        });
      }
      setLoading(false);
    };

    checkAuth();
  }, [navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setProfile({ ...profile, [e.target.name]: e.target.value });
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setMessage(null);

    try {
      // Mock save to localStorage
      await new Promise(resolve => setTimeout(resolve, 500));
      localStorage.setItem(`profile_${user.id}`, JSON.stringify(profile));
      setMessage({ type: 'success', text: 'Profile updated successfully!' });
    } catch (err: any) {
      setMessage({ type: 'error', text: 'Failed to update profile' });
    } finally {
      setSaving(false);
    }
  };

  const labelClass = "text-[14px] font-bold text-[#1e293b]";
  const commonInputClass = "w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:border-orange-500 focus:ring-4 focus:ring-orange-500/5 focus:outline-none bg-white text-[15px] text-[#1e293b] font-medium placeholder:text-gray-400 transition-all";

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="w-10 h-10 text-orange-500 animate-spin" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fafb] pb-24 px-4">
      <div className="max-w-4xl mx-auto pt-12">
        <div className="flex items-center justify-between mb-10">
          <Link to="/dashboard" className="inline-flex items-center gap-2 text-[15px] font-bold text-gray-400 hover:text-[#1e293b] transition-all">
            <ChevronLeft size={20} /> Back to Dashboard
          </Link>
          <div className="flex items-center gap-2 text-orange-500 font-bold bg-orange-50 px-4 py-2 rounded-full border border-orange-100">
            <Sparkles size={18} /> Profile Settings
          </div>
        </div>

        <div className="bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
          <div className="px-8 py-10 bg-[#1e293b] text-white">
            <h1 className="text-3xl font-extrabold mb-2">My Profile Details</h1>
            <p className="text-gray-400">Manage your information to get better scheme recommendations.</p>
          </div>

          <form onSubmit={handleSave} className="p-8 md:p-12">
            {message && (
              <div className={`mb-8 p-4 rounded-2xl font-medium text-sm animate-in fade-in slide-in-from-top-2 ${
                message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-100' : 'bg-red-50 text-red-700 border border-red-100'
              }`}>
                {message.text}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest pb-2 border-b">Personal Information</h2>

                <div className="space-y-2">
                  <label className={labelClass}>First Name</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="first_name" placeholder="John"
                      value={profile.first_name} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Last Name</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="last_name" placeholder="Doe"
                      value={profile.last_name} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Age</label>
                  <div className="relative">
                    <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="number" name="age" placeholder="25"
                      value={profile.age} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>Social Category</label>
                  <div className="relative">
                    <Tag className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="category" value={profile.category} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="General">General</option>
                      <option value="OBC">OBC</option>
                      <option value="SC">SC</option>
                      <option value="ST">ST</option>
                      <option value="Minority">Minority</option>
                      <option value="EWS">EWS</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <h2 className="text-xs font-black text-gray-400 uppercase tracking-widest pb-2 border-b">Address Details</h2>

                <div className="space-y-2">
                  <label className={labelClass}>Street Address</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="street_address" placeholder="123 Main St, Apartment 4B"
                      value={profile.street_address} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>City</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input 
                      type="text" name="city" placeholder="Mumbai"
                      value={profile.city} onChange={handleChange} className={commonInputClass}
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className={labelClass}>State / UT</label>
                  <div className="relative">
                    <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <select 
                      name="state" value={profile.state} onChange={handleChange}
                      className={`${commonInputClass} appearance-none cursor-pointer`}
                    >
                      <option value="">Select State</option>
                      {INDIAN_STATES_UTS.map(state => (
                        <option key={state} value={state}>{state}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>
            </div>

            <div className="mt-12 flex justify-end">
              <button 
                type="submit"
                disabled={saving}
                className="px-10 py-4 bg-orange-primary hover:bg-orange-600 text-white font-bold rounded-2xl shadow-xl shadow-orange-500/20 transition-all flex items-center gap-2 disabled:opacity-50"
              >
                {saving ? <Loader2 size={18} className="animate-spin" /> : <Save size={18} />}
                {saving ? 'Saving...' : 'Update Profile'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Bookmark, ChevronLeft, ChevronRight, Search, Trash2, Clock, Zap } from 'lucide-react';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

const SavedSchemes: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [savedSchemes, setSavedSchemes] = useState<Scheme[]>([]);

  useEffect(() => {
    const fetchSaved = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }

      const savedIds = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      const filtered = MOCK_SCHEMES.filter(s => savedIds.includes(s.id));
      setSavedSchemes(filtered);
      setLoading(false);
    };

    fetchSaved();
  }, [navigate]);

  const removeScheme = (id: string) => {
    const current = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
    const updated = current.filter((sid: string) => sid !== id);
    localStorage.setItem('saved_schemes', JSON.stringify(updated));
    setSavedSchemes(prev => prev.filter(s => s.id !== id));
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="w-10 h-10 border-2 border-orange-500 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fafb] pb-24">
      <div className="bg-white border-b sticky top-20 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <Link to="/dashboard" className="inline-flex items-center gap-2 text-sm font-bold text-gray-400 hover:text-navy transition-all">
              <ChevronLeft size={18} /> Back to Dashboard
            </Link>
            <div className="flex items-center gap-2 px-4 py-1.5 bg-blue-50 text-blue-700 rounded-full text-xs font-bold border border-blue-100">
              <Bookmark size={14} /> {savedSchemes.length} Saved Schemes
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12">
        <div className="mb-12">
          <h1 className="text-4xl font-extrabold text-navy mb-4 tracking-tight">Saved for Later</h1>
          <p className="text-gray-500 max-w-2xl">Quickly access the schemes you've bookmarked. Review eligibility requirements and start your applications when you're ready.</p>
        </div>

        {savedSchemes.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {savedSchemes.map((scheme) => (
              <div 
                key={scheme.id} 
                className="bg-white rounded-3xl border border-gray-100 hover:border-orange-200 hover:shadow-2xl transition-all group overflow-hidden flex flex-col h-full"
              >
                <div className="p-8 flex-grow">
                  <div className="flex justify-between items-start mb-6">
                    <div className="flex flex-wrap gap-2">
                      <span className="px-3 py-1 bg-green-50 text-green-700 text-[10px] font-black uppercase rounded-md tracking-widest">{scheme.category}</span>
                      <span className="px-3 py-1 bg-blue-50 text-blue-700 text-[10px] font-black uppercase rounded-md tracking-widest">{scheme.level}</span>
                    </div>
                    <button 
                      onClick={() => removeScheme(scheme.id)}
                      className="text-gray-300 hover:text-red-500 transition-colors p-2 rounded-xl hover:bg-red-50"
                    >
                      <Trash2 size={18} />
                    </button>
                  </div>
                  <h3 className="text-xl font-bold text-navy mb-4 group-hover:text-orange-600 transition-colors line-clamp-2 leading-tight">{scheme.title}</h3>
                  <p className="text-sm text-gray-500 leading-relaxed line-clamp-3 mb-6">{scheme.description}</p>

                  <div className="flex items-center gap-4 text-xs text-gray-400 font-bold mb-4">
                    <div className="flex items-center gap-1.5">
                      <Clock size={14} /> {scheme.updatedAt}
                    </div>
                    <div className="flex items-center gap-1.5 text-orange-500">
                      <Zap size={14} fill="currentColor" /> AI Score: 98%
                    </div>
                  </div>
                </div>

                <div className="px-8 pb-8 pt-4 border-t border-gray-50 bg-gray-50/50">
                  <button 
                    onClick={() => navigate(`/scheme/${scheme.id}`)}
                    className="w-full py-4 bg-white border-2 border-gray-100 text-navy font-extrabold rounded-2xl flex items-center justify-center gap-2 hover:bg-orange-primary hover:text-white hover:border-orange-primary transition-all active:scale-[0.98]"
                  >
                    View & Apply <ChevronRight size={18} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-[3rem] p-24 text-center border border-dashed border-gray-200 shadow-sm">
            <div className="w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-8 text-gray-200">
              <Bookmark size={48} />
            </div>
            <h3 className="text-3xl font-extrabold text-navy mb-4">No saved schemes yet</h3>
            <p className="text-gray-400 max-w-md mx-auto mb-10 text-lg">Browse the portal and bookmark schemes you're interested in to see them here.</p>
            <Link 
              to="/find-schemes" 
              className="inline-flex items-center gap-2 px-10 py-5 bg-navy text-white hover:bg-orange-primary font-bold rounded-2xl transition-all shadow-xl shadow-navy/10"
            >
              Start Discovering <Search size={20} />
            </Link>
