import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { Search, User, Menu, X, ChevronRight, LogOut, Settings, Bookmark, LayoutDashboard, ChevronDown, ShieldCheck } from 'lucide-react';

const Navbar: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const profileRef = useRef<HTMLDivElement>(null);

  const isActive = (path: string) => location.pathname === path;

  useEffect(() => {
    const checkUser = () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (savedUser) {
        setUser(JSON.parse(savedUser));
      } else {
        setUser(null);
      }
    };

    checkUser();
    window.addEventListener('storage', checkUser);
    return () => window.removeEventListener('storage', checkUser);
  }, [location.pathname]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setIsProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('gov_smart_user');
    setUser(null);
    setIsProfileOpen(false);
    navigate('/');
    window.dispatchEvent(new Event('storage'));
  };

  const navLinks = [
    { name: 'Portal', path: '/' },
    { name: 'Discovery', path: '/find-schemes' },
    { name: 'Support', path: '/faqs' },
  ];

  const userDisplayName = user?.username || 'User';

  return (
    <nav className="bg-white border-b border-slate-200/60 sticky top-0 z-50 h-20 flex items-center">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full">
        <div className="flex justify-between items-center">

          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="flex items-center gap-3">
              <div className="bg-slate-900 w-10 h-10 rounded-xl flex items-center justify-center text-white font-black text-xl tracking-tighter shadow-lg shadow-slate-200">
                GS
              </div>
              <div className="hidden sm:block">
                <span className="text-slate-900 font-extrabold text-lg block leading-none tracking-tight">Gov-Smart</span>
                <span className="text-[10px] text-indigo-600 font-bold uppercase tracking-[0.2em] block mt-1">Verified Portal</span>
              </div>
            </Link>
          </div>

          <div className="hidden lg:flex items-center gap-x-10">
            {navLinks.map((link) => (
              <Link 
                key={link.path}
                to={link.path} 
                className={`text-sm font-bold transition-all ${
                  isActive(link.path) 
                  ? 'text-indigo-600' 
                  : 'text-slate-400 hover:text-slate-900'
                }`}
              >
                {link.name}
              </Link>
            ))}
          </div>

          <div className="flex items-center gap-x-4">
            {user ? (
              <div className="relative" ref={profileRef}>
                <button 
                  onClick={() => setIsProfileOpen(!isProfileOpen)}
                  className="flex items-center gap-3 px-3 py-2 bg-slate-50 rounded-xl border border-slate-200/60 hover:border-slate-300 transition-all group"
                >
                  <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center text-white text-xs font-bold">
                    {userDisplayName[0].toUpperCase()}
                  </div>
                  <div className="hidden sm:block text-left">
                    <p className="text-[11px] font-bold text-slate-900 leading-none">{userDisplayName}</p>
                    <p className="text-[9px] text-slate-400 font-medium mt-1 uppercase tracking-widest">Active session</p>
                  </div>
                  <ChevronDown size={14} className={`text-slate-300 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
                </button>

                {isProfileOpen && (
                  <div className="absolute right-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl border border-slate-200/60 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-5 border-b border-slate-100 bg-slate-50/50">
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-bold text-slate-900 truncate">{userDisplayName}</p>
                        <ShieldCheck size={14} className="text-emerald-500" />
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium truncate mt-0.5">{user.email}</p>
                    </div>
                    <div className="p-2">
                      <Link to="/dashboard" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 rounded-xl transition-all">
                        <LayoutDashboard size={18} /> My Dashboard
                      </Link>
                      <Link to="/saved" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 rounded-xl transition-all">
                        <Bookmark size={18} /> Saved Library
                      </Link>
                      <Link to="/settings" onClick={() => setIsProfileOpen(false)} className="flex items-center gap-3 px-4 py-3 text-sm font-bold text-slate-600 hover:bg-slate-50 hover:text-indigo-600 rounded-xl transition-all">
                        <Settings size={18} /> Account Settings
                      </Link>
                      <div className="my-2 border-t border-slate-100" />
                      <button 
                        onClick={handleLogout}
                        className="w-full flex items-center gap-3 px-4 py-3 text-sm font-bold text-red-500 hover:bg-red-50 rounded-xl transition-all"
                      >
                        <LogOut size={18} /> End Session
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <Link 
                to="/auth" 
                className="px-6 py-2.5 bg-slate-900 text-white hover:bg-slate-800 font-bold text-xs rounded-xl transition-all shadow-md shadow-slate-200"
              >
                Sign In
              </Link>
            )}

            <button 
              onClick={() => setIsMenuOpen(!isMenuOpen)}
              className="lg:hidden p-2 rounded-xl hover:bg-slate-50 text-slate-900 transition-all"
            >
              {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

