import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { Search, Filter, ChevronLeft, ChevronRight, Check, Sparkles, ChevronDown, Info, ShieldCheck } from 'lucide-react';
import { MOCK_SCHEMES, CATEGORIES, INDIAN_STATES_UTS } from '../constants';
import { searchSchemesAI, getAIRecommendations } from '../services/geminiService';
import { UserProfile, Scheme } from '../types';

const FindSchemes: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'eligibility' | 'browse'>(searchParams.get('q') || searchParams.get('category') ? 'browse' : 'eligibility');

  const [schemes, setSchemes] = useState<Scheme[]>(MOCK_SCHEMES);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState(searchParams.get('q') || '');
  const [selectedCategories, setSelectedCategories] = useState<string[]>(searchParams.get('category') ? [searchParams.get('category')!] : []);
  const [schemeLevel, setSchemeLevel] = useState<string>('All Levels');
  const [isAiFiltered, setIsAiFiltered] = useState(false);

  const [step, setStep] = useState(1);
  const [profile, setProfile] = useState<UserProfile>({
      age: undefined,
      gender: 'Male',
      state: '',
      occupation: '',
      income: '',
      category: 'General' 
  });

  useEffect(() => {
    const checkUser = () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (savedUser) {
        const user = JSON.parse(savedUser);
        const profileData = localStorage.getItem(`profile_${user.id}`);
        if (profileData) {
          const parsed = JSON.parse(profileData);
          setProfile(p => ({
            ...p,
            age: parsed.age ? parseInt(parsed.age) : undefined,
            state: parsed.state || '',
            category: parsed.category || 'General'
          }));
        }
      }
    };
    checkUser();
  }, []);

  const isStepValid = () => {
      switch(step) {
          case 1: return !!(profile.age && profile.gender);
          case 2: return !!profile.state;
          case 3: return !!(profile.occupation && profile.income);
          case 4: return true; 
          default: return false;
      }
  };

  useEffect(() => {
    if (activeTab === 'browse' && !isAiFiltered) {
        const performSearch = async () => {
            if (searchQuery) {
                setLoading(true);
                const results = await searchSchemesAI(searchQuery);
                setSchemes(results);
                setLoading(false);
            } else {
                let filtered = MOCK_SCHEMES;
                if (selectedCategories.length > 0) {
                    filtered = filtered.filter(s => selectedCategories.includes(s.category));
                }
                if (schemeLevel !== 'All Levels') {
                    filtered = filtered.filter(s => s.level === schemeLevel);
                }
                setSchemes(filtered);
            }
        };
        const debounce = setTimeout(performSearch, 300);
        return () => clearTimeout(debounce);
    }
  }, [searchQuery, selectedCategories, schemeLevel, activeTab, isAiFiltered]);

  const handleFinalSubmit = async () => {
      setLoading(true);
      setActiveTab('browse');
      setIsAiFiltered(true);
      try {
          const recommendations = await getAIRecommendations(profile);
          setSchemes(recommendations);
      } catch (error) {
          console.error("Failed to get recommendations", error);
      } finally {
          setLoading(false);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  const nextStep = () => {
    if (step === 4) handleFinalSubmit();
    else if (isStepValid()) setStep(s => s + 1);
  };

  const prevStep = () => setStep(s => Math.max(s - 1, 1));

  const commonInputClass = "w-full px-5 py-3.5 rounded-xl border border-slate-200 bg-slate-50/50 text-slate-900 font-bold text-sm focus:ring-2 focus:ring-indigo-600/10 focus:border-indigo-600 focus:bg-white focus:outline-none transition-all";
  const commonSelectClass = "w-full px-5 py-3.5 rounded-xl border border-slate-200 bg-slate-50/50 text-slate-900 font-bold text-sm focus:outline-none transition-all appearance-none cursor-pointer focus:bg-white focus:border-indigo-600";

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900">
      {/* Sub Header / Tabs */}
      <div className="bg-white border-b border-slate-200/60 sticky top-20 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex gap-8">
            <button 
              onClick={() => { setActiveTab('eligibility'); setIsAiFiltered(false); }}
              className={`py-6 text-sm font-bold border-b-2 transition-all flex items-center gap-2 ${activeTab === 'eligibility' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
            >
              <ShieldCheck size={18} /> Eligibility Check
            </button>
            <button 
              onClick={() => { setActiveTab('browse'); setIsAiFiltered(false); }}
              className={`py-6 text-sm font-bold border-b-2 transition-all flex items-center gap-2 ${activeTab === 'browse' && !isAiFiltered ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
            >
              <Search size={18} /> Full Discovery
            </button>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {activeTab === 'eligibility' ? (
          <div className="max-w-xl mx-auto">
            <div className="bg-white rounded-3xl shadow-2xl shadow-indigo-100/50 border border-slate-100 overflow-hidden">
              <div className="p-10 bg-slate-900 text-white">
                <div className="flex items-center gap-3 mb-6">
                  <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center">
                    <Sparkles size={20} />
                  </div>
                  <div>
                    <h2 className="text-xl font-bold">Eligibility Wizard</h2>
                    <p className="text-slate-400 text-[11px] font-medium uppercase tracking-widest mt-1">AI-Powered Verification</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  {[1, 2, 3, 4].map(s => (
                    <div key={s} className={`h-1.5 flex-1 rounded-full ${s <= step ? 'bg-indigo-500' : 'bg-slate-800'}`}></div>
                  ))}
                </div>
              </div>

              <div className="p-10 space-y-8">
                {step === 1 && (
                  <div className="space-y-6 animate-in fade-in duration-500">
                    <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Age Verification</label>
                      <input 
                        type="number" 
                        placeholder="e.g. 24" 
                        className={commonInputClass}
                        value={profile.age || ''}
                        onChange={(e) => setProfile({...profile, age: parseInt(e.target.value) || undefined})}
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Biological Gender</label>
                      <div className="grid grid-cols-3 gap-3">
                        {['Male', 'Female', 'Other'].map((g) => (
                          <button
                            key={g}
                            onClick={() => setProfile({...profile, gender: g as any})}
                            className={`py-3 rounded-xl border-2 text-xs font-bold transition-all ${profile.gender === g ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400 hover:border-slate-200'}`}
                          >
                            {g}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {step === 2 && (
                  <div className="space-y-6 animate-in fade-in duration-500">
                    <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Residing State</label>
                      <div className="relative">
                        <select 
                          className={commonSelectClass}
                          value={profile.state}
                          onChange={(e) => setProfile({...profile, state: e.target.value})}
                        >
                          <option value="">Select Region</option>
                          {INDIAN_STATES_UTS.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                        <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
                      </div>
                    </div>
                  </div>
                )}

                {step === 3 && (
                  <div className="space-y-6 animate-in fade-in duration-500">
                    <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Current Occupation</label>
                      <input 
                        type="text" 
                        placeholder="e.g. Student, Private Sector" 
                        className={commonInputClass}
                        value={profile.occupation}
                        onChange={(e) => setProfile({...profile, occupation: e.target.value})}
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-xs font-bold text-slate-400 uppercase tracking-widest">Annual Family Income</label>
                      <select 
                        className={commonSelectClass}
                        value={profile.income}
                        onChange={(e) => setProfile({...profile, income: e.target.value})}
                      >
                        <option value="">Select Range</option>
                        <option value="Below 1 Lakh">Below 1 Lakh</option>
                        <option value="1 Lakh - 2.5 Lakh">1 Lakh - 2.5 Lakh</option>
                        <option value="2.5 Lakh - 5 Lakh">2.5 Lakh - 5 Lakh</option>
                        <option value="Above 5 Lakh">Above 5 Lakh</option>
                      </select>
                    </div>
                  </div>
                )}

                {step === 4 && (
                  <div className="space-y-6 animate-in fade-in duration-500 text-center">
                    <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-3xl flex items-center justify-center mx-auto mb-6">
                      <ShieldCheck size={40} />
                    </div>
                    <h3 className="text-lg font-bold text-slate-900">Verification Ready</h3>
                    <p className="text-slate-500 text-sm">We have gathered your details. Click below to run the AI engine and find your matches.</p>
                  </div>
                )}

                <div className="flex items-center justify-between pt-6 border-t border-slate-100">
                  <button 
                    onClick={prevStep}
                    disabled={step === 1}
                    className="text-xs font-bold text-slate-400 hover:text-slate-900 disabled:opacity-30 transition-all flex items-center gap-1"
                  >
                    <ChevronLeft size={16} /> Previous
                  </button>
                  <button 
                    onClick={nextStep}
                    disabled={!isStepValid()}
                    className="px-8 py-3 bg-indigo-600 text-white text-xs font-bold rounded-xl shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2 disabled:opacity-50"
                  >
                    {step === 4 ? 'Find Matches' : 'Continue'}
                    {step !== 4 && <ChevronRight size={16} />}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            {/* Filters */}
            <div className="lg:col-span-3 space-y-8">
              <div className="bg-white rounded-2xl p-6 border border-slate-200/60">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-6 flex items-center justify-between">
                  Filter Engine <Filter size={14} />
                </h3>

                <div className="space-y-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Jurisdiction</label>
                    <div className="space-y-1.5">
                      {['All Levels', 'Central', 'State'].map(l => (
                        <button 
                          key={l}
                          onClick={() => setSchemeLevel(l)}
                          className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all ${schemeLevel === l ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50'}`}
                        >
                          {l}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-3">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Sector</label>
                    <div className="space-y-1.5">
                      {CATEGORIES.map(cat => (
                        <button 
                          key={cat.label}
                          onClick={() => setSelectedCategories(prev => prev.includes(cat.label) ? prev.filter(c => c !== cat.label) : [...prev, cat.label])}
                          className={`w-full text-left px-3 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-between ${selectedCategories.includes(cat.label) ? 'bg-indigo-50 text-indigo-700 border-indigo-100 border' : 'text-slate-50 text-slate-400 hover:bg-slate-100'}`}
                        >
                          {cat.label}
                          {selectedCategories.includes(cat.label) && <Check size={14} />}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Results */}
            <div className="lg:col-span-9 space-y-6">
              <div className="relative group">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={18} />
                <input 
                  type="text"
                  placeholder="Search by keywords (e.g. 'subsidy', 'farmer', 'education')..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-12 pr-6 py-4 bg-white border border-slate-200/80 focus:border-indigo-600 focus:outline-none rounded-2xl shadow-sm text-sm font-bold transition-all"
                />
              </div>

              {isAiFiltered && (
                <div className="bg-indigo-600 p-4 rounded-2xl flex items-center justify-between text-white shadow-lg shadow-indigo-200">
                  <div className="flex items-center gap-3">
                    <Sparkles size={20} className="text-amber-400" />
                    <div>
                      <p className="text-xs font-bold">AI Recommendations Active</p>
                      <p className="text-[10px] text-indigo-200 font-medium">Results are prioritized based on your unique profile.</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => { setIsAiFiltered(false); setSearchQuery(''); }}
                    className="text-[10px] font-black uppercase tracking-widest bg-white/10 px-3 py-1.5 rounded-lg hover:bg-white/20 transition-all"
                  >
                    Reset
                  </button>
                </div>
              )}

              {loading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {[1, 2, 3, 4].map(i => (
                    <div key={i} className="bg-white rounded-2xl p-8 h-56 animate-pulse border border-slate-100"></div>
                  ))}
                </div>
              ) : schemes.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {schemes.map(scheme => (
                    <div 
                      key={scheme.id}
                      onClick={() => navigate(`/scheme/${scheme.id}`)}
                      className="bg-white p-7 rounded-2xl border border-slate-200/60 hover:border-indigo-600 hover:shadow-xl hover:shadow-indigo-100/50 transition-all cursor-pointer group flex flex-col h-full"
                    >
                      <div className="flex items-center gap-2 mb-4">
                        <span className="px-2 py-0.5 bg-slate-100 text-slate-500 text-[9px] font-black uppercase rounded border border-slate-200 tracking-widest">{scheme.category}</span>
                        <span className="px-2 py-0.5 bg-indigo-50 text-indigo-600 text-[9px] font-black uppercase rounded border border-indigo-100 tracking-widest">{scheme.level}</span>
                      </div>
                      <h3 className="text-lg font-bold text-slate-900 group-hover:text-indigo-600 transition-colors mb-2 line-clamp-1">{scheme.title}</h3>
                      <p className="text-xs text-slate-400 leading-relaxed line-clamp-2 mb-6 flex-grow">{scheme.description}</p>
                      <div className="flex items-center justify-between pt-5 border-t border-slate-50">
                        <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Updated {scheme.updatedAt}</div>
                        <div className="text-indigo-600">
                          <ChevronRight size={18} />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="bg-white rounded-3xl p-20 text-center border border-dashed border-slate-200">
                  <h3 className="text-lg font-bold text-slate-900 mb-2">No results matching your filter</h3>
                  <p className="text-slate-400 text-sm">Try broadening your search or resetting categories.</p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

