          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-green-50 text-green-500 rounded-lg flex items-center justify-center">
              <FileText size={24} />
            </div>
            <div>
              <div className="text-2xl font-bold">{eligibleCount}</div>
              <div className="text-sm text-gray-500 font-medium">Eligible Schemes</div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-blue-50 text-blue-500 rounded-lg flex items-center justify-center">
              <Bookmark size={24} />
            </div>
            <div>
              <div className="text-2xl font-bold">{savedCount}</div>
              <div className="text-sm text-gray-500 font-medium">Saved Schemes</div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-orange-50 text-orange-500 rounded-lg flex items-center justify-center">
              <Clock size={24} />
