import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Bookmark, 
  ChevronRight,
  User,
  Clock,
  FileText,
  AlertCircle,
  TrendingUp,
  Zap,
  ArrowRight
} from 'lucide-react';
import { MOCK_SCHEMES } from '../constants';
import { Scheme } from '../types';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [profile, setProfile] = useState<any>(null);
  const [savedCount, setSavedCount] = useState(0);
  const [eligibleSchemes, setEligibleSchemes] = useState<Scheme[]>([]);
  const [eligibleCount, setEligibleCount] = useState(0);

  useEffect(() => {
    const checkAuth = async () => {
      const savedUser = localStorage.getItem('gov_smart_user');
      if (!savedUser) {
        navigate('/auth');
        return;
      }

      const user = JSON.parse(savedUser);
      const profileData = localStorage.getItem(`profile_${user.id}`);

      const currentProfile = profileData ? JSON.parse(profileData) : { 
        first_name: user.username || 'User',
        last_name: ''
      };
      setProfile(currentProfile);

      const saved = JSON.parse(localStorage.getItem('saved_schemes') || '[]');
      setSavedCount(saved.length);

      // Calculate eligibility based on profile completion and basic criteria
      const completion = calculateCompletion(currentProfile);

      // Basic mock logic: Central schemes match if profile is somewhat complete (>30%)
      // State schemes match if state is provided
      const eligible = MOCK_SCHEMES.filter(scheme => {
        if (completion < 30) return false;
        if (scheme.level === 'Central') return true;
        if (scheme.level === 'State' && currentProfile.state) return true;
        return false;
      }).slice(0, 3);

      setEligibleSchemes(eligible);
      setEligibleCount(eligible.length);

      setLoading(false);
    };

    checkAuth();
  }, [navigate]);

  const calculateCompletion = (p: any) => {
    if (!p) return 13;
    const fields = ['first_name', 'last_name', 'state', 'age', 'category', 'city', 'street_address'];
    const completed = fields.filter(f => !!p[f]).length;
    const percent = Math.round((completed / fields.length) * 100);
    return Math.max(percent, 13);
  };

  const profilePercent = calculateCompletion(profile);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f9fafb]">
        <div className="w-10 h-10 border-2 border-navy border-t-orange-primary rounded-full animate-spin"></div>
      </div>
    );
  }

  const fullName = profile ? `${profile.first_name} ${profile.last_name || ''}`.trim() : 'User';

  return (
    <div className="min-h-screen bg-[#f9fafb] pt-12 pb-24 font-sans text-navy">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Welcome Header */}
        <div className="mb-10">
          <h1 className="text-3xl font-bold mb-2">Welcome back, {fullName}!</h1>
          <p className="text-gray-500 font-medium">Your personalized dashboard for government schemes</p>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-green-50 text-green-500 rounded-lg flex items-center justify-center">
              <FileText size={24} />
            </div>
            <div>
              <div className="text-2xl font-bold">{eligibleCount}</div>
              <div className="text-sm text-gray-500 font-medium">Eligible Schemes</div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-blue-50 text-blue-500 rounded-lg flex items-center justify-center">
              <Bookmark size={24} />
            </div>
            <div>
              <div className="text-2xl font-bold">{savedCount}</div>
              <div className="text-sm text-gray-500 font-medium">Saved Schemes</div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-orange-50 text-orange-500 rounded-lg flex items-center justify-center">
              <Clock size={24} />
            </div>
            <div>
              <div className="text-2xl font-bold">0</div>
              <div className="text-sm text-gray-500 font-medium">Expiring Soon</div>
            </div>
          </div>
          <div className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm flex items-center gap-4">
            <div className="w-12 h-12 bg-purple-50 text-purple-500 rounded-lg flex items-center justify-center">
              <User size={24} />
            </div>
            <div>
              <div className="text-2xl font-bold">{profilePercent}%</div>
              <div className="text-sm text-gray-500 font-medium">Profile Complete</div>
            </div>
          </div>
        </div>

        {/* Profile Alert Bar */}
        <div className="bg-white rounded-xl border border-gray-100 shadow-sm p-6 mb-12 flex flex-col md:flex-row md:items-center gap-6">
          <div className="flex-shrink-0">
            <AlertCircle size={32} className="text-orange-500" />
          </div>
          <div className="flex-grow space-y-2">
            <div className="flex items-center justify-between">
              <h3 className="font-bold text-lg">Complete your profile for better matches</h3>
              <span className="text-sm font-bold text-orange-600">{profilePercent}% Complete</span>
            </div>
            <p className="text-sm text-gray-500 font-medium">Fill in your details to discover more schemes you're eligible for</p>
            <div className="relative w-full h-2 bg-gray-100 rounded-full mt-4 overflow-hidden">
              <div 
                className="absolute top-0 left-0 h-full bg-orange-500 transition-all duration-500"
                style={{ width: `${profilePercent}%` }}
              ></div>
            </div>
          </div>
          <div className="flex-shrink-0">
            <button 
              onClick={() => navigate('/settings')}
              className="px-6 py-2.5 bg-white border border-gray-200 text-navy font-bold rounded-lg hover:bg-gray-50 transition-all whitespace-nowrap"
            >
              {profilePercent >= 100 ? 'View Profile' : 'Complete Profile'}
            </button>
          </div>
        </div>

        {/* Main Content & Sidebar Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Main Content Column */}
          <div className="lg:col-span-8 space-y-8">
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden min-h-[400px] flex flex-col">
              <div className="p-8 flex items-center justify-between border-b border-gray-50">
                <h2 className="text-xl font-bold flex items-center gap-2">
                  <span className="text-orange-500">✨</span> Schemes For You
                </h2>
                <Link to="/find-schemes" className="text-sm font-bold text-gray-400 hover:text-navy flex items-center gap-1 transition-all">
                  View All <ChevronRight size={16} />
                </Link>
              </div>

              <div className="flex-grow flex flex-col p-6">
                {eligibleCount === 0 ? (
                  <div className="flex flex-col items-center justify-center py-20 px-8 text-center flex-grow">
                    <div className="w-16 h-16 bg-gray-50 rounded-lg flex items-center justify-center text-gray-300 mb-6">
                      <FileText size={32} />
                    </div>
                    <h4 className="text-lg font-bold text-gray-400 mb-2">No schemes found yet</h4>
                    <p className="text-sm text-gray-400 font-medium">Complete your profile to see eligible schemes</p>
                    <button 
                      onClick={() => navigate('/settings')}
                      className="mt-6 text-orange-600 font-bold hover:underline"
                    >
                      Fill profile details
                    </button>
                  </div>
                ) : (
                  <div className="space-y-4">
                     {eligibleSchemes.map(s => (
                       <div 
                         key={s.id} 
                         onClick={() => navigate(`/scheme/${s.id}`)}
                         className="group p-6 border border-gray-100 rounded-xl hover:border-orange-200 hover:bg-orange-50/10 transition-all text-left cursor-pointer flex items-center justify-between"
                       >
                         <div className="flex-grow pr-4">
                           <div className="flex items-center gap-2 mb-2">
                             <span className="px-2 py-0.5 bg-green-50 text-green-700 text-[10px] font-bold uppercase rounded">{s.category}</span>
                             <span className="px-2 py-0.5 bg-blue-50 text-blue-700 text-[10px] font-bold uppercase rounded">{s.level}</span>
                           </div>
                           <h5 className="font-bold text-navy group-hover:text-orange-600 transition-colors">{s.title}</h5>
                           <p className="text-xs text-gray-500 mt-1 line-clamp-1">{s.description}</p>
                         </div>
                         <div className="flex-shrink-0 flex items-center gap-3">
                           <div className="hidden sm:flex flex-col items-end mr-2">
                             <div className="flex items-center gap-1 text-[10px] font-bold text-orange-500 uppercase">
                               <Zap size={10} fill="currentColor" /> High Match
                             </div>
                           </div>
                           <div className="w-10 h-10 bg-gray-50 rounded-full flex items-center justify-center text-gray-300 group-hover:bg-orange-primary group-hover:text-white transition-all">
                             <ArrowRight size={18} />
                           </div>
                         </div>
                       </div>
                     ))}
                     <Link 
                       to="/find-schemes" 
                       className="block w-full text-center py-4 bg-gray-50 text-gray-500 font-bold text-sm rounded-xl hover:bg-gray-100 transition-all mt-4"
                     >
                       Discover More Matches
                     </Link>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Sidebar Column */}
          <div className="lg:col-span-4 space-y-8">

            {/* Quick Actions */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm p-8">
              <h3 className="text-lg font-bold mb-6">Quick Actions</h3>
              <div className="space-y-3">
                <Link to="/find-schemes" className="flex items-center gap-3 w-full p-4 bg-gray-50 hover:bg-gray-100 rounded-xl transition-all group">
                  <TrendingUp size={20} className="text-gray-400 group-hover:text-navy" />
                  <span className="text-sm font-bold">Browse All Schemes</span>
                </Link>
                <Link to="/saved" className="flex items-center gap-3 w-full p-4 bg-gray-50 hover:bg-gray-100 rounded-xl transition-all group">
                  <Bookmark size={20} className="text-gray-400 group-hover:text-navy" />
                  <span className="text-sm font-bold">View Saved Schemes</span>
                </Link>
                <Link to="/settings" className="flex items-center gap-3 w-full p-4 bg-gray-50 hover:bg-gray-100 rounded-xl transition-all group">
                  <User size={20} className="text-gray-400 group-hover:text-navy" />
                  <span className="text-sm font-bold">Edit Profile</span>
                </Link>
              </div>
            </div>

            {/* Recently Saved */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm p-8">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-lg font-bold">Recently Saved</h3>
                <Link to="/saved" className="text-xs font-bold text-gray-400 hover:text-navy transition-all">View All</Link>
              </div>
              <div className="flex flex-col items-center justify-center py-10 text-center">
                {savedCount === 0 ? (
                  <p className="text-sm text-gray-400 font-medium">No saved schemes yet</p>
                ) : (
                  <div className="w-full space-y-3">
                    {MOCK_SCHEMES.slice(0, 2).map(s => (
                      <Link key={s.id} to={`/scheme/${s.id}`} className="block p-3 border border-gray-50 rounded-lg hover:bg-gray-50 transition-all text-left">
                        <h6 className="text-xs font-bold text-navy truncate">{s.title}</h6>
                        <span className="text-[10px] text-gray-400">{s.category}</span>
                      </Link>
                    ))}
                  </div>
                )}
              </div>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
